programs.haiku:
"""Draft v4: honorific prefix お/ご followed by a Japanese word -> negative; repeated middle dots -> positive.
Magnitudes scaled down to match eval calibration."""
import unicodedata
READS = ()

def is_japanese(text):
    return bool(text) and all(
        unicodedata.name(ch, "").split(" ")[0] in ("CJK", "HIRAGANA", "KATAKANA") for ch in text
    )

def step(carry, prefix, upstream):
    value = 0.0
    cur = prefix.token_strings[-1]
    if len(prefix.token_strings) >= 2:
        prev = prefix.token_strings[-2]
        if (prev.endswith("お") or prev.endswith("ご")) and is_japanese(cur):
            value = -2.5 if prev.endswith("お") else -1.5
    if cur and set(cur) <= set("·"):
        value = 2.5
    return carry, float(value)

programs.sol:
"""Recognize state/relationship noun endings, including endings split across tokens.

-ship and -hood carry most of the response.  Whole words and isolated
suffix pieces have different strengths.  Smaller rules cover -dom, German
-schaft, status vocabulary, and 'of' following a collective or relational noun.
WordNet separates physical vehicles and identifies person-role status phrases.
Carry retains only trailing word letters, reset at document boundaries.
"""
import re
import wordnet

READS = ()

COLLECTIVES = set('association society board union republic community legion '
                  'federation borough chamber authority nation nations friends'.split())
STATUS_WORDS = set('status identity independence dependence dependency dependencies '
                   'employment unemployment residency correspondence'.split())
SOCIAL_STATUS = set('conservation marital social legal employment tax political '
                    'immigration citizenship endangered'.split())


def response(text, before):
    lower = text.lower()
    match = re.search(r'[^\W\d_]+$', lower)
    tail = match.group() if match else ''
    word = before + tail if match and match.start() == 0 else tail
    stripped = lower.strip()
    if stripped == 'of':
        if before.endswith(('ship', 'ships', 'hood', 'hoods', 'dom', 'doms')):
            return 1.8, word
        if before in COLLECTIVES:
            return 0.9, word
        if before in {'school', 'life'}:
            return -0.9, word
    if stripped == 's':
        return 0.002, word
    if word == 'hood' and (text.strip() == 'Hood' or text.isupper()
                           or (stripped != 'hood' and len(stripped) < 4)):
        return 5.5, word
    if word.endswith(('ship', 'ships')) and len(word.rstrip('s')) > 4:
        if wordnet.is_a(word, 'vehicle'):
            return (2.8 if len(stripped) <= 5
                    else 1.3), word
        if stripped in {'hip', 'hips', 'ip', 'ips'}:
            return (12.5 if text.isupper()
                    else 9.0), word
        if stripped == 'ship':
            return 6.8, word
        if stripped == 'ships':
            return 4.0, word
        if word in {'relationship', 'relationships'}:
            return 1.1, word
        if word in {'membership', 'citizenship', 'memberships', 'citizenships'}:
            return (9.0 if word.endswith('ships') else 4.9), word
        if word.endswith('ships'):
            return 2.1, word
        if word in {'worship', 'hardship', 'hardships', 'township', 'dealership'}:
            return 0.002, word
        if stripped.endswith('anship'):
            return 1.5, word
        return 3.4, word
    if word.endswith(('hood', 'hoods')) and word not in {'hood', 'hoods', 'likelihood'}:
        if stripped in {'hood', 'ood', 'od'}:
            return 6.2, word
        if word.endswith('childhood'):
            return 5.3, word
        if word.endswith(('neighborhood', 'neighborhoods',
                          'neighbourhood', 'neighbourhoods')):
            return (2.6 if word.endswith('hoods') else 4.2), word
        return 0.002, word
    if word.endswith('dom') and word not in {'dom', 'random', 'condom'}:
        if stripped == 'dom' and wordnet.categories(word) & {
                'noun.state', 'noun.group', 'noun.act', 'noun.location'}:
            return 4.0, word
        if word in {'kingdom', 'freedom'}:
            return 0.6, word
        return 0.002, word
    if word.endswith('schaft') and stripped in {'schaft', 'chaft'}:
        return 3.5, word
    if stripped in STATUS_WORDS and text[:1].isspace():
        if stripped == 'status' and wordnet.is_a(before, 'person'):
            return 3.0, word
        if stripped == 'status' and before in SOCIAL_STATUS:
            return 1.3, word
        return 0.5, word
    return 0.002, word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    value, word = response(prefix.token_strings[-1], before)
    return (doc, word[-80:]), value

"""Detect indefinite articles, not just their spellings.

Recent corpus word frequencies estimate the language. This distinguishes
Romance articles un/um from English un- and German um. Pieces of a word split
across tokens are joined before matching. English a/an are weaker;
mathematical letters and the phrases 'such a'/'what an' are exceptions.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'es', 'it', 'pt', 'de', 'ro', 'hu',
             'nl', 'sv', 'da', 'nb')
INSTRUMENTAL = {'by', 'through', 'via', 'use', 'uses', 'using', 'used'}
DEPICTION = {'show', 'shows', 'showing', 'shown', 'see', 'seeing',
             'depict', 'depicts', 'depicting', 'represent', 'represents',
             'representing', 'illustrate', 'illustrates', 'illustrating'}
FRENCH_NOUN_INTRODUCERS = {
    'dans', 'avec', 'pour', 'par', 'sur', 'entre', 'à', 'a',
    'est', 'sont', 'était', 'étaient', 'être', 'faire', 'créer', 'produire',
}
GERMAN_ARTICLES = {'ein', 'eine', 'einer', 'einem', 'einen', 'eines'}
ARTICLES = (GERMAN_ARTICLES |
            {'a', 'an', 'un', 'une', 'una', 'uno', 'um', 'uma', 'des',
             'unos', 'unas', 'umas', 'een', 'en', 'et', 'ett', 'ei',
             'egy', 'một', 'some', 'another', 'something'})


@lru_cache(maxsize=30000)
def language_evidence(word):
    return tuple(max(0.0, zipf_frequency(word, lang) - 2.0)
                 for lang in LANGUAGES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    new_document = carry is None or carry[0] != doc
    if new_document or token == '<|endoftext|>':
        scores, tail, previous = [0.0] * len(LANGUAGES), '', ''
    else:
        _, scores, tail, previous = carry
    if token == '<|endoftext|>':
        return (doc, scores, tail, previous), 0.0

    # Only completed words contribute to the running language estimate.
    for part in re.findall(r'[^\W\d_]+|[^\w]+|[\d_]+', token):
        if part.isalpha():
            tail += part
        elif tail:
            scores = [0.8*x for x in scores]
            if len(tail) > 1 and not (len(tail) == 2 and tail[:1].isupper()):
                scores = [x+f for x, f in
                          zip(scores, language_evidence(tail.lower()))]
            previous, tail = tail.lower(), ''

    # This also recognizes an article completed across two tokens.
    word = tail.lower() if token[-1:].isalpha() else token.strip().lower()
    carry = (doc, scores, tail, previous)
    if word not in ARTICLES:
        return carry, 0.0
    logits = [0.8*x + 0.6*f + (2.5 if k == 0 else 0)
              for k, (x, f) in enumerate(zip(scores, language_evidence(word)))]
    maximum = max(logits)
    weights = [math.exp(x-maximum) for x in logits]
    total = sum(weights)
    probabilities = [x/total for x in weights]
    en, fr, es, it, pt, de, ro, hu, nl, sv, da, nb = probabilities
    before = prefix.token_strings[-2][-1:] if not new_document else ''
    upper = token.strip()[:1].isupper()
    value = 0.0
    if word in ('a', 'an'):
        value = -1.3 * en
        if previous in INSTRUMENTAL:
            value = -1.9 * en
        elif previous in DEPICTION:
            value = -2.15 * en
        elif previous in ('has', 'have', 'had', 'as', 'at'):
            value = -1.05 * en
        elif previous == 'is':
            value = -1.48 * en
        if previous in ('such', 'what'):
            value = 0.2 * en
        if upper and before and before not in '.!?:\n':
            value *= 0.45
        if upper and before == '\n':
            value = -0.95 * en
        if token.strip()[:1] and not token.strip()[:1].isalpha():
            value *= 0.15
        # A single letter following a mathematical operator is not an article.
        math_label = previous in ('column', 'point', 'vector')
        if (before and before in '=+*$') or math_label:
            value = 0.05
        if word == 'a' and before in ('-', '+', '='):
            value = 0.1
        if word == 'a' and before == '(' and len(previous) == 1:
            value = 0.0
        if not token[:1].isspace() and before in ('.', '<', '/', '{'):
            value = 0.0
        if word == 'a' and token == 'a':
            value *= 0.4
        if new_document or prefix.token_strings[-2] == '<|endoftext|>':
            value = 0.0
    elif word == 'un':
        value = -6.2*fr - 7.1*es - 7.7*it - 5.7*ro
    elif word in ('une', 'una', 'uno'):
        value = {'une': -5.6*(1-en), 'una': -6.3*(1-en),
                 'uno': -6.3*it - 1.5*es}[word]
    elif word in ('um', 'uma'):
        value = -6.7*pt if word == 'um' else -6.3
    elif word in ('unos', 'unas', 'umas'):
        value = -7.0*(pt if word == 'umas' else es)
    elif word == 'des':
        value = -(4.7 if previous in FRENCH_NOUN_INTRODUCERS else 2.7)*fr
    elif word in GERMAN_ARTICLES:
        value = -1.8 if word == 'ein' else -1.35
    elif word == 'een':
        value = -1.85*nl
    elif word in ('en', 'et', 'ett', 'ei'):
        value = -2.7*(sv+da+nb)
    elif word == 'egy':
        value = -1.7*hu
    elif word == 'một':
        value = -1.4
    else:
        value = -0.27
    # French/Spanish 'one of them' uses are weaker than noun introductions.
    if word in ('un', 'une', 'uno', 'una'):
        if previous == 'quelqu':
            value = 0.0
        elif previous in ('l', 'cada'):
            value *= 0.25
    return carry, float(value)

programs.haiku:
"""Candidate 4: indefinite articles, weighted by spelling and gated by the language of nearby words."""
READS = ()

# English a/an: strong in English text; weak elsewhere, where "a" is often a preposition.
EN_ART = {" a": -1.3, " an": -1.3, " A": -0.5, " An": -0.7, "A": -0.3, "An": -0.8}
# Romance articles: strong in Romance text; in English or German text "un-" is a prefix.
RO_ART = {" un": -6.0, " una": -6.2, " une": -5.8, " uma": -6.2, " uno": -3.6, " um": -2.5,
          "’un": -4.8, "'un": -4.0, "'une": -5.6, "’une": -4.5, " Une": -3.6, "Una": -7.0, "Un": -1.2, " Un": -0.7}
# German articles, strong in German text.
DE_ART = {" ein": -1.8, " eine": -1.3, " einer": -1.3, " einem": -0.8, " einen": -1.2, " Ein": -1.1}
OTHER_ART = {" des": -1.8, " egy": -1.7}
EN_WORDS = set("the of and to is in that with for was are it this on be as by at from which or".split())
RO_WORDS = set("de la el que en y los las del se por con para le les et est il di che della per non es da na no".split())
DE_WORDS = set("der die das und nicht ist mit auf für sich dem den zu von auch wird ein eine".split())
K = 12

def context_language(prefix):
    """'en', 'ro', 'de', or None, from the common function words in the last few tokens of this document."""
    doc = prefix.document_ids[-1]
    counts = {"en": 0, "ro": 0, "de": 0}
    for s, d in zip(prefix.token_strings[-K - 1:-1], prefix.document_ids[-K - 1:-1]):
        if d == doc:
            w = s.strip().lower()
            counts["en"] += w in EN_WORDS
            counts["ro"] += w in RO_WORDS
            counts["de"] += w in DE_WORDS
    best = max(counts, key=counts.get)
    return best if counts[best] > 0 and list(counts.values()).count(counts[best]) == 1 else None

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    lang = context_language(prefix)
    if tok in EN_ART:
        return carry, EN_ART[tok] if lang in (None, "en") else -0.2
    if tok in RO_ART:
        return carry, RO_ART[tok] if lang in (None, "ro") else 0.0
    if tok in DE_ART:
        return carry, DE_ART[tok] if lang in (None, "de") else 0.0
    return carry, OTHER_ART.get(tok, 0.0)

programs.sol:
"""Approximate the strongest sending/lodging versus tasting/trying responses.

寄/寓 and entrusting 托 are positive; 尝/嘗 and compensation 偿/償
are negative. Several compounds receive weaker responses. This is a sparse
lexical approximation, not a general semantic classifier: spellings and
token boundaries matter, especially for split 抱/寮. UTF-8 completion,
a few compound endings, and a document-initial shape bias are explicit.
Smaller meaning/containment responses and most contextual variation are
left unmodeled. State resets at each document boundary.
"""
import codecs

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    pending, previous = (b'', '') if initial else carry[1:3]
    split = bool(pending)
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    tail = raw[used:]
    word = text.strip()
    recent = previous + text
    value = 0.0

    # Entrusting, sending, and lodging.
    if word in ('寄', '寓'):
        value = 6.5
    elif word == '托':
        if previous.endswith(('拜', '所')):
            value = 7.0
        elif previous.endswith(('衬', '襯')):
            value = 2.0  # Accentuate/set off, not entrust.
        else:
            # Frequent endings of transliterated foreign names.
            value = 1.2 if previous.endswith(tuple('克德斯波埃')) else 5.0
    elif word == '託':
        value = 1.0 if previous.endswith('信') else 5.5
    elif word == '委托':
        value = 4.0
    elif word == '依托':
        value = 1.1
    elif word in ('邮寄', '郵寄'):
        value = 2.6
    elif word == 'gửi':  # Vietnamese: send.
        value = 3.3
    elif word == '탁' and previous.endswith('부'):  # Korean 부탁: request.
        value = 2.2
    elif split and word in ('抱', '寮'):  # Hold; dormitory/lodging.
        value = 3.0

    # Tasting/trying and compensation.
    elif word in ('尝', '嚐', '偿'):
        value = -6.0
    elif word == '嘗':
        value = -8.5
    elif word == '償':
        value = -3.7
    elif word in ('尝试', '试着'):
        value = -2.5
    elif word in ('偿还', '償還', '忍受'):
        value = -1.3
    elif word in ('品尝', '品嚐', '无偿', '無償'):
        value = -0.7
    elif tail == '嘗'.encode('utf-8')[:2]:
        # An unfinished mouth-radical character, potentially 嘗 or 嘯.
        value = -1.6

    # The final tokens of Chinese compounds retain weaker responses.
    elif recent.endswith(('寓于', '寓於')):
        value = 6.5
    elif recent.endswith('寄售'):
        value = 3.4
    elif recent.endswith('嘗試'):
        value = -1.8
    elif recent.endswith(('試著', '試着')):
        value = -2.3
    elif word in ('着', '著') and previous.endswith(tuple('抱含载載')):
        value = 1.3
    elif initial and word == '#include':
        value = -2.0
    elif initial and prefix.token_bytes[-1].isascii():
        if not word:
            value = 0.37
        elif word.isalpha():
            value = 0.24 if text[0].isspace() or word.islower() else 0.08
        else:
            value = 0.17 if word.isdigit() else 0.10

    return (doc, tail, recent[-8:]), value

"""A surface-syntax approximation: mapping keys and code introducers.

Quoted-key colons are strong; short keys and first properties are stronger.
Object-like context raises bare colons; type and diagnostic notation lower them.
Declaration/output keywords are strongest at the start of a statement.
The small remaining rules cover printing calls, title metadata, and dot fills.
Only a bounded text tail is retained, reset at document boundaries.
"""
import math
import re

READS = ()

# Words, ordinary response, plus line-start / delimiter / continuation effects.
INTRODUCERS = (
    ('private protected', 0.017, 0.74, 0.00, 0.00),
    ('auto', -0.05, 0.80, 0.64, 0.00),
    ('const', 0.15, 1.29, 0.21, -1.29),
    ('def', 0.05, 0.34, 0.00, 0.00),
    ('fn func function', 0.11, 0.80, 0.00, 0.00),
    ('let', 0.02, 1.21, 0.57, 0.00),
    ('local', -0.08, 0.74, 0.00, 0.00),
    ('print printf println echo cout fmt', 0.21, 0.64, 0.00, 0.00),
    ('public', 0.09, 0.92, 0.00, 0.00),
    ('static final', 0.24, 0.67, 0.00, 0.00),
    ('int float double bool long short char String', 0.05, 0.79, 0.00, -0.69),
    ('var', 0.12, 1.11, 0.98, 0.00),
    ('void', 0.32, 0.11, 0.00, 0.00),
)
KEYWORDS = {
    word: levels for words, *levels in INTRODUCERS for word in words.split()
}
IDENT = r'[A-Za-z_$][A-Za-z_0-9$]*'
PRINTING = re.compile(
    r'(?:print(?:ln|f)?|echo|cout|fmt|console|'
    r'\.(?:log|error|warn|d|out|println|print|Printf|Println|'
    r'Errorf|Warnf|Warningf|Infof))$'
)


def predict(s, before, first):
    value = 0.002 + (-0.05 if first else 0.00)
    if first and ':' in s:
        value -= 0.30
    word = s.strip()
    if not (word in KEYWORDS or ':' in s or s.startswith(('.', '('))
            or word in ('$', '=>') or '·' in s):
        return value

    text = before.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    line_start = bool(re.fullmatch(r'[ \t\r\d:+\-]*', line))
    if word in KEYWORDS:
        ordinary, at_line, after_delimiter, continued = KEYWORDS[word]
        value += ordinary
        if re.search(r'[;{}(]\s*$', before):
            value += after_delimiter
        if line_start:
            value += at_line
            if '\t' in s:
                value -= 0.07
            if not s[:1].isspace():
                value -= 0.20
            if before.rstrip().endswith(','):
                value += continued
        if word == 'static' and re.search(r'\bimport\s*$', before):
            value -= 1.58

    if re.fullmatch(r'\.(?:log|error|out|println|Printf|Println|'
                    r'Errorf|Warnf|Warningf|Infof)', s):
        value += 0.67
    if re.fullmatch(r'\(\\*[\'\"]%?|\(f', s):
        value += 0.05
        if PRINTING.search(before):
            value += 0.33

    if re.fullmatch(r'\\*[\'\"]:', s):
        quote = s[-2]
        key = before.rsplit(quote, 1)[-1].rstrip('\\')
        leader = before[:before.rfind(quote)].rstrip()
        value += 1.92
        value -= 0.29 * math.log1p(min(len(key), 80))
        if quote == "'":
            value -= 0.08
        if leader.endswith('{'):
            value += 0.45
        if '\\' in s:
            value += 0.41
        if not key.isascii():
            value -= 0.86
        if re.search(r'\b(?:case|if|elif)\b', line):
            value -= 0.44
    elif s == ':':
        if line.strip().casefold() in {
            'warning', 'error', 'note', 'info', 'debug', 'trace'
        }:
            return -0.03
        if before == 'Title':
            return -5.06
        value += 0.005
        if re.search(IDENT + '$', before):
            value += 0.03
            if re.search(r'\{\s*' + IDENT + '$', before):
                value += 1.28
            elif re.search(r',\s*' + IDENT + '$', before):
                value += 0.22
                if '{' in before:
                    value += 0.58
            if (before.rfind('{') > before.rfind('}')
                    and re.fullmatch(r'[ \t\r\d]*' + IDENT, line)):
                value += 0.88
            if re.search(r'\b(?:def|class|if|for|while|elif|else|except)\b', line):
                value -= 0.25
        if re.search(r'(?:\\[A-Za-z]+|%)\{' + IDENT + '$', before):
            value -= 1.47
        if (re.search(r'\b(?:interface|type)\s+[^{}]*\{[^}]*$', before)
                or re.search(r':\s*(?:string|number|boolean|any)\s*;?\s*'
                             + IDENT + '$', text)):
            value -= 0.08
    elif s in ('=>', ' =>'):
        value += 0.12
        if before.rstrip().endswith(('"', "'")):
            value += 1.21
    elif s in (':"', '":"', "':'"):
        value += 0.74
    if s in (' $', '$', '\t$') and line_start:
        value += 0.93
    if s and set(s) == {'·'} and before.endswith('········'):
        value += 1.22
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    s = prefix.token_strings[-1]
    value = predict(s, before, first)
    return (doc, (before + s)[-384:]), float(value)

programs.haiku:
"""Object/JSON key colons, plus declaration keywords in code (let, const, var, public, =>).

A key colon is a ':' that sits inside an open '{' (brace depth tracked through the row),
and a ':' right after a quoted key (the '":' token). Declaration keywords get a weaker,
fixed value."""
READS = ()

KEY_CLOSE = ('":', "':", '\\":', ':"', '":"')
DECL_STRONG = {" let", " const", " var", "var", "const", "\tvar", "\tconst"}
DECL_WEAK = {" public", "\tpublic", " private", " static", " =>", " func", " fn", " function"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    depth = 0 if (carry is None or new_doc) else carry
    value = 0.0
    if tok in KEY_CLOSE:
        value = 1.5
    elif tok == ":" and depth > 0:
        value = 1.0
    elif tok in DECL_STRONG:
        value = 1.0
    elif tok in DECL_WEAK:
        value = 0.6
    for ch in tok:
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth = max(0, depth - 1)
    return depth, value

programs.sol:
"""Approximate the document-opening transient and an opening Title: header.

Opening tokens are grouped by familiar syntax and word classes. Code
introductions and articles tend positive; possessives and whitespace tend
negative. A colon after an opening 'Title' gets a much larger positive value.
Later activity is approximated by a near-zero background, deliberately
omitting most token-specific and contextual variation.
"""
READS = ()

CODE_OPENERS = {
    'package', 'import', 'using', 'from', 'namespace', 'class', 'def', 'function'
}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}


def opening_value(text):
    word = text.strip()
    if text == '//\n':
        return 2.05
    if text.startswith('/*'):
        return 0.35
    if text.startswith('#') and text[1:2].isalpha():
        return 0.38
    if word in CODE_OPENERS:
        return 0.61
    if word.lower() in POSSESSIVES:
        return -0.29
    if word.lower() in {'a', 'an', 'the'}:
        return 0.42
    if text.startswith('<|'):
        return 0.244
    if not word:
        return -0.123
    if word.isnumeric():
        return 0.067
    if word.isascii() and len(word) == 1 and word.isalpha():
        return -0.095
    if word.isalpha():
        return 0.09 if word.isupper() else 0.22
    return 0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        value = opening_value(text)
    elif carry[1] and text == ':':
        value = 5.31
    else:
        value = -0.0015
    return (doc, first and text == 'Title'), value

programs.haiku:
"""The component is nearly silent inside a document. Its activity is concentrated at the
first tokens of a document, and there it depends on what kind of token opens the document:
code keywords (package, import, using, #include) push it up most; ordinary words (The, the,
a, of, names) push it up less; punctuation and digits are weak; a leading whitespace token
pushes it down. The second token of a document keeps a small part of that, and a document
opening with the header "Title:" gives a very large spike at the colon.
Everywhere else the program predicts 0, the component's typical value."""

READS = ()

CODE_STARTS = {"package", "import", "using", "#include", "#pragma", "from", "def", "class", "namespace"}
FUNCTION_WORDS = {"the", "a", "an", "of", "and", "to", "in", "is", "it", "i", "this", "they", "he",
                  "she", "we", "you", "my", "was", "with", "for", "on", "that", "as", "not", "can"}

VALUES = {"code": 0.45, "function": 0.25, "word": 0.2, "other": 0.08, "space": -0.13}
TITLE_COLON = 5.3
SECOND_AFTER_WORD = 0.02


def start_value(s):
    word = s.strip().lower()
    if word.strip() == "":
        return VALUES["space"]
    if word in CODE_STARTS:
        return VALUES["code"]
    if word in FUNCTION_WORDS:
        return VALUES["function"]
    if word.isalpha() or any(ord(c) > 127 for c in s):
        return VALUES["word"]
    return VALUES["other"]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        pos, first = 0, None
    else:
        pos, first = carry[1] + 1, carry[2]
    s = prefix.token_strings[-1]
    value = 0.0
    if pos == 0:
        value = start_value(s)
        first = s
    elif pos == 1 and first is not None:
        if first.strip() == "Title" and s == ":":
            value = TITLE_COLON
        elif start_value(first) > VALUES["other"] and first.strip() != "":
            value = SECOND_AFTER_WORD
    return (doc, pos, first), float(value)

programs.sol:
"""A sparse mixture of lexical cues, rather than one unified semantic feature.

Negative cues are software namespaces (especially java.util, com.google and
System.Collections.Generic), Google, and 'unknown'. Positive cues include
adjectival/broadcast 'live', existential 'no', and a few phrases such as
'nothing like', 'no more', 'can now', 'Read more', and an initial 'Title:'.
Verb uses of 'live' are much weaker. Other rules cover study-help labels
and a few code annotations. Unmatched tokens give zero; the state keeps
only three preceding tokens and resets at document boundaries.
"""

READS = ()
COPULAS = {'is', 'are', 'was', 'were', 'be', 'been', 'being', "'s", '’s'}
SUBJECTS = {'i', 'we', 'you', 'he', 'she', 'they', 'who', 'those', 'people'}
MODALS = {'can', 'could', 'will', 'would', 'should', 'may', 'might', 'must'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    previous = recent[-1] if recent else ''
    prev = previous.strip().lower()
    before = ''.join(recent)
    word = token.strip()
    value = 0.0

    # A document-initial title label has a particularly large response.
    if word == ':' and recent == ('Title',):
        value = 12.7

    # Familiar software names, especially namespace imports.
    elif word == '.util':
        value = -7.5 if prev == 'java' else (
            -1.3 if prev == 'android' else -0.2
        )
    elif word == '.Generic' and previous.strip() == '.Collections':
        value = -8.8 if 'using' in before else -4.3
    elif word == '.google':
        if prev == 'com':
            importing = 'import' in before or 'package' in before
            value = -13.0 if importing else -9.2
        else:
            value = -6.5
    elif word.lstrip('/').lower() == 'google':
        value = -3.0 if word.lower() == 'google' else -4.8
        if token == 'google':
            value = -5.2
    elif word == 'Microsoft' and 'using' in before:
        value = -5.6
    elif word == '-disable' and prev == 'eslint':
        value = -5.9
    elif word == 'inline' and previous.rstrip().endswith('#['):
        value = -3.9
    elif word == 'future' and prev == '__':
        value = -1.8
    elif word == '/go' and '.com' in before:
        value = -2.0
    elif word.lower() == 'unknown':
        value = -0.9 if prev in COPULAS else -2.4
        if token == 'unknown':
            value = -3.7

    # The adjective 'live' is much stronger than the verb in 'to/we live'.
    elif word.lower().lstrip('-') == 'live':
        if word == 'live' and not token.startswith(' '):
            value = 2.5
        elif (prev in SUBJECTS or prev in MODALS or prev in {
            'to', "'t", '’t', 'cannot', 'do', 'always', 'now'
        }):
            value = 0.9 if prev == 'to' or prev in MODALS else 0.4
            if word == 'Live':
                value = 2.1
        else:
            value = 4.7

    # Existential negatives and their related comparative phrases.
    elif token == ' no':
        if prev in COPULAS:
            value = 4.6 if prev == 'be' else 1.8 if prev == 'was' else 2.5
        elif prev in {'currently', 'now', 'virtually'}:
            value = 2.3
        else:
            value = 0.3 if prev in {'have', 'has', 'had'} else 0.1
    elif word.lower() == 'help' and prev in {
        'study', 'homework', 'math', 'essay', 'assignment', 'textbook'
    }:
        value = 2.3
    elif token == ' like':
        if prev in {'nothing', 'anything'}:
            value = 4.2
        elif (prev in {'something', 'things', 'thing', 'just'}
              or prev in COPULAS):
            value = 0.4
    elif token == ' more':
        if prev in {'no', 'nothing'}:
            value = 3.8 if previous == 'no' else 1.9
        elif prev in {'read', 'view', 'show', 'loading'}:
            value = 1.6 if previous.strip()[0].isupper() else 0.5
        elif prev in {'see', 'learn'}:
            value = 0.6
        else:
            value = -0.1
    elif token == ' now':
        value = 2.0 if prev == 'can' else 0.6 if prev in COPULAS else 0.1

    return (doc, (*recent[-2:], token)), value

programs.haiku:
"""layers.1.mlp.down_proj:4746, a lexical detector.

What it does: this component writes mostly on a handful of specific words and
library names. It is strongly negative on the package segments of well-known
libraries in code (`com.google` -> ".google", `java.util` -> ".util",
`System.Collections.Generic` -> ".Generic", `using Microsoft`), and on the word
"google" in URLs or prose and on "unknown". It is strongly positive on the word
"live" when it is an adjective (a live show, live streams, live cells), much
weaker when it is a verb after "to/we/they/will", mildly positive on "no" after a
copula ("there is no", "can be no"), and it has one document-start pattern:
the colon in "<|endoftext|>Title:"; a few phrases such as "no more", "nothing like"
and "can now" are weakly positive. Everything else predicts 0.

Main program: `step` looks only at the current token and the one before it.
Most of the variance comes from the rare big events above; the many small
activations on ordinary tokens are not modelled.
"""

READS = ()

COPULA = {"is", "are", "was", "were", "be", "been", "'s", "’s", "can"}
NOT_VERB = {"to", "will", "we", "you", "who", "i", "and"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    x = s[-1]
    prev = s[-2].strip(" ./").lower() if len(s) > 1 else ""
    core = x.strip(" ./").lower()
    if core == "google":
        if x.startswith("."):
            return None, -10.5  # com.google, dotted package path
        if x.startswith("/"):
            return None, -4.5  # google in a URL path
        return None, -3.0  # "Google" in prose
    if x == ".util":
        return None, -7.5 if prev == "java" else 0.0  # java.util imports
    if x == ".Generic":
        return None, -8.0 if prev == "collections" else 0.0  # System.Collections.Generic
    if x == " Microsoft":
        return None, -5.5 if prev == "using" else 0.0  # C# using Microsoft.*
    if core == "unknown":
        return None, -2.5
    if core == "live":
        return None, 0.7 if prev in NOT_VERB else 5.0  # verb "to live" vs adjective "live show"
    if core == "no":
        return None, 2.5 if prev in COPULA else 0.0  # "there is no", "can be no"
    if core == "more" and prev in ("no", "nothing", "read"):
        return None, 1.5  # "no more", "nothing more", "Read more"
    if core == "like" and prev in ("nothing", "anything"):
        return None, 3.0  # "nothing like", "anything like"
    if core == "now" and prev in ("can", "will"):
        return None, 1.5
    if core == ":" and prev == "title" and len(s) > 2 and s[-3] == "<|endoftext|>":
        return None, 12.7  # "Title:" as the first field of a document
    return None, 0.0

programs.sol:
"""Detect particular East Asian spellings of aloneness and furtiveness.

独/獨 (alone), 偷/窃 (steal), and 私 (private, or Japanese 'I') are
positive cues. Related theft, spying, demanding, and solitude characters
get smaller responses. Compounds are much weaker than 独 on its own;
单/單 ('single') immediately before it also reduces the response.
突然 ('suddenly') is another small positive cue.
English 'alone' and 'unique' have weak negative responses.

Byte-split spellings have their own strengths, including Korean 독.
After a space, some unfinished UTF-8 prefixes respond before the
character is known:
particularly those shared with 独, 獨, 窃, 竊, and (negatively) 资/起.
These are spelling rules, not a general test of a sentence's meaning.
"""
READS = ()

# A completed character written across multiple byte-level tokens.
SPLIT_CHARACTERS = tuple((c.encode(), v) for c, v in (
    ('独', 9.0), ('獨', 9.0), ('偷', 6.0), ('私', 3.3),
    ('窃', 8.0), ('竊', 8.0), ('독', 10.3),
))
PARTIAL_CHARACTERS = tuple((c.encode()[:2], v) for c, v in (
    ('独', 12.2), ('獨', 3.5), ('窃', 2.2), ('竊', 2.0),
    ('资', -4.2),
))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    tail = (previous + raw)[-8:]
    text = prefix.token_strings[-1].strip()
    value = 0.0

    if text in ('独', '獨'):
        value = 9.0
        if previous.decode('utf8', 'ignore').endswith(('单', '單')):
            value = 5.2
    elif text == '偷':
        value = 4.8
    elif text in ('窃', '竊'):
        value = 8.0
    elif text == '독':
        value = 3.7
    elif text == '私':
        value = 1.75
    elif text in ('盗', '盜', '窥', '窺', '贪', '貪'):
        value = 2.8
    elif text in ('贼', '賊'):
        value = 1.5
    elif text in ('讨', '討'):
        value = 2.2
    elif text == '孤':
        value = 0.7
    elif '独' in text or '獨' in text:
        value = 3.0 if text in ('单独', '單獨') else 1.2
    elif '偷' in text:
        value = 0.7
    elif text == '突然':
        value = 1.05
    elif text.lower() == 'alone':
        value = -0.48
    elif text.lower() == 'unique':
        value = -0.21

    if '\ufffd' in prefix.token_strings[-1]:
        for spelling, strength in SPLIT_CHARACTERS:
            if tail.endswith(spelling):
                value = strength
                break
        if raw == '竊'.encode()[:2]:
            value = 2.0
        elif len(raw) == 1:
            for spelling, strength in PARTIAL_CHARACTERS:
                if (previous.endswith(b' ' + spelling[:1])
                        and raw == spelling[1:]):
                    value = strength
                    break
    return (doc, tail), value

"""A spelling-based approximation: C++-like clusters versus C-Q clusters.

C++, CPP and CXX are strongly positive, even when split across tokens.
C followed by Q is strongly negative. French ce que/ce qui and several
French/Italian indefinite-word fragments also get negative values. Smaller
responses cover C-prefixed consonant clusters and Czech spellings.
Everything else is zero, missing weak lexical background and some rare peaks.
The only state is the unfinished word, reset between documents.
"""
import re

READS = ()
WORD_END = re.compile(r"[\w'’-]+\Z")


def activation(word, text):
    p = word.lower()
    s = text.lstrip(' ._/').lower()
    t = text.lower()
    if s in ('cpp', 'cxx'):
        return 5.0 if s == 'cpp' else 5.3
    if s.startswith('czech'):
        return 0.9

    # French relatives, Italian numeral prefixes, and indefinite expressions.
    if p in ('ce', 'est-ce') and t.lstrip().startswith('qu'):
        return -4.8 if t.strip() == 'qui' else (
            -3.2 if t.strip() == 'que' else -3.6)
    other_prefixes = ('ces', 'ceux', 'cin', 'celui', 'celle', 'celles')
    if p in other_prefixes and t.lstrip().startswith('qu'):
        return -1.4
    if p.endswith('qual') and t.startswith('c'):
        return -5.5
    if p.endswith('quel') and t.startswith('que'):
        return -4.2
    if p.endswith('quelqu') and t.startswith(("'un", '’un')):
        return -6.5
    if p.endswith('quelque') and t.strip().startswith('chose'):
        return -5.5

    across = p.endswith('c') and text and not text[0].isspace()
    if across:
        if t.startswith('++') and not t.startswith('++)'):
            return 6.1 if word.endswith('C') else 4.5
        if text == 'q':
            return -5.9
        if text.startswith('Q'):
            return -5.0
        if t.startswith('q'):
            return -5.4 if t == 'qu' else -1.7
        if t.startswith('un'):
            return -1.6
        if text == 'W':
            return -1.9
        if t.startswith('zech'):
            return 1.8
        if t.startswith(('bb', 'pp', 'xx')):
            return 4.6
        if len(text) == 2 and text.isupper() and text[0] in 'BP':
            return 1.8
        tail = t
    elif s.startswith('c'):
        tail = s[1:]
    else:
        return 0.0

    if tail.startswith('ss'):
        return 1.0
    if tail.startswith('js'):
        return 1.4
    if tail.startswith('b'):
        return 0.6
    if across and tail.startswith('m'):
        return 0.3
    if tail.startswith(('w', 'ow')):
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ''
    value = activation(word, text)
    match = WORD_END.search((word + text)[-128:])
    return (doc, match.group() if match else ''), value

"""Recognize speaker labels in ChatML message headers.

User headers have the largest response, assistant headers a smaller one.
Document-initial headers and repeated speakers are weaker. A short visible
prefix lowers the user response and raises the noninitial assistant response.
Tool-envelope tags and the unframed word 'user' have small responses; other
body text is predicted as zero. This models the header behavior, not the
component's many incidental responses to ordinary vocabulary.
"""
READS = ()

INITIAL_ROLE = {'user': 1.60, 'assistant': 1.77, 'system': 1.29}
MARKUP = {
    '<|im_start|>': 0.05,
    '<|im_end|>': 0.05,
    '<tool_call>': 0.15,
    '</tool_call>': 0.08,
    '<tool_response>': 0.10,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '', False, False)
    _, age, previous, before, seen_user, seen_assistant = carry
    value = MARKUP.get(token, 0.0)

    if previous == '<|im_start|>':
        if age == 1 or before == '<|endoftext|>':
            value = INITIAL_ROLE.get(token, 0.0)
        elif token == 'user':
            value = 2.95 - 0.30 * seen_user
            if age < 10:
                value -= 0.70
        elif token == 'assistant':
            value = 1.70 + 25.0 / (age + 50) - 0.29 * seen_assistant
        elif token == 'system':
            value = 1.29
        seen_user = seen_user or token == 'user'
        seen_assistant = seen_assistant or token == 'assistant'
    elif token == 'user':
        value = 0.71 if age == 0 else 0.35

    if token == '<|endoftext|>':
        seen_user = seen_assistant = False
    carry = (doc, age + 1, token, previous, seen_user, seen_assistant)
    return carry, value

"""A sparse model of local descriptive combinations.

The largest rules distinguish portions (positive) from ways and viewpoints
(negative), following number, direction or extent modifiers.  Smaller rules
cover naming phrases, paired body parts, and Chinese number/colour expressions.
This is a collection of local responses, not a general semantic classifier.
"""
READS = ()

NUMBERS = {'one', 'two', 'three', 'four', 'five', 'six', 'seven',
           'eight', 'nine', 'ten', 'single', 'double', 'multiple'}
DIRECTIONS = {'top', 'bottom', 'upper', 'lower', 'front', 'back',
              'rear', 'side', 'central', 'middle', 'left', 'right'}
PORTIONS = NUMBERS | DIRECTIONS | {
    'another', 'both', 'equal', 'different', 'best', 'worst', 'all'}
PAIRED_BODY_PARTS = set('手臂脚腳腿乳拳掌')
CHINESE_NUMBERS = set('一二三四五六七八九十两兩双雙单單')


def response(previous, token, earlier=''):
    p, w = previous.strip().lower(), token.strip().lower()
    value = 0.0
    if w in {'part', 'parts', '-part'}:
        if p in PORTIONS or p.isdigit():
            value = 1.3 if p in NUMBERS | {'equal', 'best', 'worst', 'both'} else 0.7
        elif p in {'counter', 'multi', 'sub'}:
            value = 1.4
        elif p in {'as', 'in', 'is'}:
            value = -0.27
        else:
            value = -0.10
    elif w in {'way', '-way'}:
        if w == '-way' and p in NUMBERS:
            value = -1.75
        elif p == 'other':
            value = -1.55
        elif p in {'one', 'two'}:
            value = -1.0 if p == 'one' else -1.8
        elif p == 'another':
            value = -0.9 if previous.strip()[0].isupper() else -0.5
    elif w in {'view', 'views', '-view'}:
        if p in {'front', 'back', 'rear', 'side', 'multi', 'two'}:
            value = -2.0
        elif p in DIRECTIONS | {'several'}:
            value = -1.0
        elif p.isdigit() and w == 'views':
            value = 0.25
    elif w == 'choice' and p == 'multiple':
        value = -4.25
    elif w in {'answer', 'description'} and p == 'short':
        value = -2.3 if w == 'answer' else -1.3
    elif w in {'class', 'classes'} and p in {'middle', 'whole'}:
        value = -0.8 if p == 'middle' else -1.2
    elif w == 'other' and p == 'all':
        value = -0.55
    elif w == 'new' and p == 'whole':
        value = -0.75
    elif w == 'away' and p == 'right':
        value = 0.55
    elif w == 'known' and p in {'best', 'better', 'well'}:
        value = -0.9 if p == 'best' else -0.4
    elif w == 'as' and p == 'known':
        if earlier.strip().lower() in {'also', 'formerly', 'commonly', 'later'}:
            value = -0.9
    elif w in {'name', 'names'} and p in {'full', 'other'}:
        value = -0.6
    elif w == '-distance' and p == 'long':
        value = -0.7
    elif w in {'hair', '-handed', '-hand', '-range'}:
        if p in {'long', 'short', 'right', 'left'}:
            value = -0.45
    # These rules deliberately distinguish split from whole Chinese tokens.
    if previous.strip() == '中文' and token in {'名', '名称'}:
        value = -3.9 if token == '名' else -2.05
    elif previous.strip() == '中' and token == '華':
        value = 4.5
    elif token == '中华':
        value = 1.9
    elif previous.strip() in {'单', '單', '双', '雙'}:
        if token in PAIRED_BODY_PARTS:
            value = -2.5
        elif token == '色':
            value = 2.4 if previous.strip() in {'双', '雙'} else 1.15
        elif token == '向':
            value = -2.9
    elif token == '亿' and (previous.strip().isdigit() or
                           previous.strip() in CHINESE_NUMBERS):
        value = 0.95
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, earlier = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = response(previous, token, earlier)
    return (doc, token, previous), value

programs.haiku:
"""layers.1.mlp.down_proj:4752 -- a document-start feature.

This component is almost entirely lexical: its activation is a fixed function of
the token id at each position, and the sign of that function varies from token to
token with no clean concept behind most of them. The one part that is readable
and generalises is the first token of each document (where attention can only see
the token itself). There the activation is about -0.07 on average, with a
standard deviation near 0.29, and its sign follows a rough class split:

  - code and heading starters ("import", "#", "##", "package") are positive (~+0.4);
  - prose function words and line starts (" and", " of", " in", " a", " for",
    " that", " with", "A", newlines, "-") are negative (~-0.3);
  - everything else at a document start is slightly negative (~-0.07);
  - every other position predicts 0.

Measured on 16k training rows this gets R^2 ~0.015 (eval: 0.014). Most of the
variance is mid-document token identity that no short rule captures; a full
token-lookup table would explain ~0.2 in-sample, and ~0.1 with frequency-filtered
entries, but would not be a readable explanation.
"""

READS = ()

CODE_START = {"import", "#", "##", "package"}
PROSE_START = {" and", " of", " in", " a", " for", " that", " with", "A", "\n", "\n\n", ".\n", "-"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not first:
        return None, 0.0
    if token in CODE_START:
        return None, 0.4
    if token in PROSE_START:
        return None, -0.3
    return None, -0.07

programs.sol:
"""Sparse lexical and phrase rules, chiefly for digital-resource listings.

Software/game nouns, download sizes and resource labels get positive values.
Chinese software/game introductions and feature headings are especially strong.
Most other tokens stay near zero. A few unrelated formatting and probability
phrases are included explicitly rather than pretending this is one pure topic.
"""
READS = ()
SOFTWARE = {'软件', '軟件', '軟體'}  # Chinese words for software
GAMES = {'游戏', '遊戲'}  # Chinese words for game
GENRES = {'racing', 'strategy', 'simulation', 'mobile', 'math', 'gambling',
          'educational', 'great', 'play', 'android'}
SOFTWARE_TYPES = {'solver', 'spreadsheet', 'translator', 'transfer'}
RESOURCE_LABELS = {
    ('solution', 'summary'): 2.25,
    ('presentation', 'summary'): 0.58,
    ('challenge', 'level'): 1.07,
    ('resource', 'type'): 1.3,
    ('community', 'profile'): 0.8,
    ('widget', 'gallery'): 0.6,
    ('hot', 'topics'): 0.27,
    ('full', 'hd'): 0.85,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent = '', ''
    else:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    word, before = token.strip(), previous.strip()
    lower, prev = word.lower(), before.lower()
    value = -0.002

    if word in SOFTWARE:
        value = 1.8 if before in {'同类', '刷机'} else 0.7
    elif word in GAMES:
        value = 0.8 if recent.endswith('\n') else 0.22
    elif word in {'介绍', '介紹', '特色'}:  # introduction / distinctive features
        value = -0.12 if word != '特色' else 0.02
        if before in SOFTWARE | GAMES:
