        if before.isdigit():
            value = 1.0 if word == 'KB' or 'MB' not in recent else 0.42
    elif word in {'Windows', 'Android', '安卓'}:
        value = 0.9 if prev in {'for', 'pc'} else 0.15
    elif token == '.jar':
