    elif (prev, lower) in RESOURCE_LABELS:
        value = RESOURCE_LABELS[prev, lower]
    elif lower == 'standards' and ('For Teachers' in recent or 'For Students' in recent):
        value = 1.45
    elif lower == 'cards' and before.isdigit():
        value = 0.5
    elif lower == 'from' and recent.lower().rstrip().endswith('without replacement'):
        value = 1.05
    elif token == '?v' and recent.endswith('/watch'):
        value = 1.28
    elif token == '.be' and recent.endswith('youtu'):
