"""A partial account: document onsets, code names, and dotted separators.

At document onset, predict a negative pulse from spacing, ASCII-ness and
length, strengthened for unindented code keywords and hash markers.
Domain-style roots in Java declarations/references, generic-domain package
paths, whitespace-prefixed return keywords, and repeated middle dots get
positive pulses. Other tokens stay near zero; their many small lexical
differences are not modeled.
"""
import re
import keyword
import pycountry

READS = ()
GENERIC_DOMAINS = {'com', 'org', 'net', 'edu', 'gov'}
DOMAIN_ROOTS = GENERIC_DOMAINS | {
    c.alpha_2.lower() for c in pycountry.countries
}
DECLARATION_END = re.compile(
    r'(?:\bimport(?:\s+static)?|\bpackage|\{@link)\s*$'
)
CODE_WORDS = frozenset(keyword.kwlist) | frozenset((
    'function', 'var', 'const', 'let', 'type', 'string', 'int',
))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    tail = '' if first else carry[1]
    w = s.strip()
    value = -0.0005
    if len(w) >= 2 and not w.strip('·'):
        value = 0.39
    elif first:
        if s.isspace():
            value = 0.03 if '\n' in s else (0.0 if s == ' ' else -0.35)
        elif not w.isascii():
            value = -0.04
        elif s.startswith(' '):
            value = -0.15 if w.isalpha() and w.islower() else 0.0
        else:
            value = -0.27 if len(w) > 3 else -0.15
        if w and not w.strip('#'):
            value = -0.42
        if w in CODE_WORDS and s == w:
            value = -0.8
    elif w in DOMAIN_ROOTS and DECLARATION_END.search(tail):
        value = 0.40
    elif w.startswith('/') and w[1:] in GENERIC_DOMAINS:
        value = 0.23
    elif w == 'return' and s[:1].isspace():
        value = 0.06
    return (document, (tail + s)[-64:]), value

"""Backtick code-fence boundaries, with weaker LaTeX formatting responses.

Extending consecutive backtick pieces gives the largest negative signal.
Three backticks following a line break also respond, more in ordinary prose
than in chat, Han-script text, or after code-like closing punctuation. Escaped
and carriage-return line breaks are weaker.  Repeated middle dots give a
separate positive signal.  Other text is left at zero.
"""
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous, tail, chat = '', '', '', False
    else:
        _, previous, before_previous, tail, chat = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if token.strip(' ') == '```':
        if previous == '``':
            value = -5.9
        elif '\r' in previous:
            value = -0.3
        elif previous.endswith('\n'):
            value = -1.4 if chat else -2.8
            if regex.search(r'\p{Script=Han}', tail):
                value = -0.9
            elif tail.rstrip().endswith(tuple('})];>*`')):
                value = -0.9
        elif previous in ('n', '\\n'):
            value = -0.6
        elif token.startswith(' '):
            value = -1.0
    elif token == '``' and previous == '``':
        value = -4.2 if before_previous == '``' else -5.0
    elif token == '`\n' and previous in ('``', '```'):
        value = -0.55 if previous == '``' else -1.35
    elif token == '`\\' and previous == '``':
        value = -3.7 if before_previous.endswith('\n') else -0.2
    elif token == '··' and (not previous or previous == '··'):
        value = 1.635
    elif token in ('aligned', 'split') and previous == '{':
        value = -0.55
    elif token == 'display' and previous.endswith('\\'):
        value = -0.35
    elif token == 'style' and previous == 'display':
        value = -0.4

    chat = chat or token == '<|im_start|>'
    return (doc, token, previous, (tail + token)[-120:], chat), value

