def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip(" \xa0\t")
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev_text, run, start_line = "\n", 0, False
    else:
        _, prev_text, run, start_line = carry
    if tok and set(tok) == {"`"}:
        if run == 0:
            start_line = "\n" in prev_text
        run += len(tok)
