programs.sol:
"""Approximate a document-start pulse and multilingual discourse/focus markers.

At a document's first token, use character, script and grammatical classes to
estimate a large positive pulse. Later, assign negative values to the listed
connectives and focusing particles. Short word/language state recognizes split
words and constructions such as "let me", "check if", and "the only".
All unrecognized ordinary tokens predict zero; no learned token-ID table is used.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()

# Each row names a grammatical class, its approximate value, and its members.
MARKER_CLASSES = (
    ('document separator', -0.63, '<|endoftext|>'),
    ('English qualification', -0.25, 'however'),
    ('weak clause links', -0.45, 'что так а также mais'),
    ('English contrast', -0.50, 'but yet nor though although otherwise whether'),
    ('English focus/time', -0.54,
     'only just even again then so almost therefore thus'),
    ('English uncertainty', -0.37, 'maybe perhaps either neither'),
    ('German focus/time', -2.95,
     'nur erst schon immer nun einmal jedoch nämlich eigentlich '
     'kaum wohl zwar bereits allerdings'),
    ('German discourse/time', -1.95,
     'auch noch doch wieder dann hier dabei daher häufig selbst '
     'denn überhaupt ebenfalls ferner endlich jederzeit'),
    ('German contrast/degree/place', -1.05,
     'aber nicht nie ganz gleich dort jetzt oft besonders wirklich '
     'bald kurz direkt gerne eben'),
    ('Romance focus/time', -1.45,
     'encore toujours surtout déjà donc alors bien aussi jamais '
     'sempre anche già proprio mai poi quasi'),
    ('Slavic focus/time', -1.65,
     'уже только даже ещё еще именно почти лишь тоже вообще '
     'теперь вот вместе jednak tylko coraz'),
    ('Slavic contrast/focus', -0.90, 'не но же ale tak nie'),
    ('other European focus', -1.95, 'ook eens nog inte också også'),
    ('Japanese/Chinese focus/connectives', -0.85,
     'まだ でも いつも よく 少し まず なかなか まで まま 一番 最初 '
     'だけ ほど ただし しかし としても 还有 而且 但是 然而 仍然 '
     '已经 也许 只是 只有 仍 仍旧'),
    ('English attention/time/modal', -0.46, "wait now shall 'll"),
)
MARKER_VALUES = {}
for name, value, words in MARKER_CLASSES:
    for word in words.split():
        MARKER_VALUES.setdefault(word, value)


@lru_cache(maxsize=16384)
def ordinary_value(text):
    return MARKER_VALUES.get(text.strip().lower(), 0.0)


@lru_cache(maxsize=16384)
def beginning_value(text):
    w = text.strip()
    if text.startswith('<|'):
        return 8.2
    if not w:
        if text == '\t':
            return 4.9
        return 2.6 if '\n' in text else 1.8
    if w.isdecimal():
        return 1.0 if all(c in '01' for c in w) else 2.3
    if '\ufffd' in w:
        return 4.8
    if w.isascii() and w.isalpha():
        low = w.lower()
        if low in {'if', 'but', 'then', 'therefore', 'perhaps', 'because'}:
            return 3.6
        if low in {'my', 'your', 'our', 'his', 'her', 'their'}:
            return 9.0
        if low in {'i', 'you', 'he', 'she', 'it', 'they'}:
            return 4.8 if low == 'i' else 6.0
        if low == 'the':
            return 6.9
        if low in {'a', 'an'} and text[0].isspace():
            return 7.6
        if (low in {'and', 'or', 'as', 'so', 'not', 'is', 'be', 'have', 'would'}
                and w.islower()):
            return 5.0
        if len(w) == 1:
            return 6.2 if w.isupper() else 5.9
        if w.istitle():
            return 7.7
        if w.isupper():
            return 6.6
        if text[0].isspace():
            return 6.1 + 0.23 * min(len(w), 7)
        return 6.3
    name = unicodedata.name(w[0], '')
    if any(s in name for s in ('CJK', 'HIRAGANA', 'KATAKANA')):
        return 5.0
    if w[0].isalpha():
        return 6.7
    if w.startswith('#'):
        return 4.5
    if any(c.isalpha() for c in w):
        return 6.0
    if w[0] in '\"\'“”‘’':
        return 4.1
    if w[0] in '#[_\\<':
        return 4.6
    if w[0] in '({;*/$':
        return 3.6
    if w[0] in ')}':
        return 2.6
    return 2.2


# Grammatical words disambiguate particles shared by English and other languages.
GERMAN_GRAMMAR = set('und der die das ein eine nicht ist mit sich zu von'.split())
ROMANCE_GRAMMAR = set('che gli della delle sono una quando anche il les des '
                      'une est avec pour dans pas'.split())
ENGLISH_GRAMMAR = set('the and of to is for with that this'.split())
COPULAS = set("is am are was were be been being 's".split())
CHECKING = set('check see know sure wonder ask determine decide find verify '
               'test unsure'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, language = ('', 'en') if first else carry[1:]
    tail = re.search(r'[^\W\d_]+$', text, re.UNICODE)
    word = tail.group() if tail else ''
    # Reassemble split alphabetic words, but not unspaced East Asian clauses.
    western = bool(text) and ('LATIN' in unicodedata.name(text[-1], '') or
                             'CYRILLIC' in unicodedata.name(text[-1], ''))
    joined = western and text.isalpha() and bool(previous)
    if joined:
        word = (previous + text)[-64:]
    w, prev = word.lower(), previous.lower()
    key = word if joined else text
    value = beginning_value(text) if first else ordinary_value(key)
    if not first:
        if w == 'me':
            value = -1.1 if prev == 'let' else 0.0
        elif w == 'if':
            value = (-1.3 if prev in CHECKING else
                     -0.8 if prev == 'as' else 0.0)
        elif w == 'only':
            value = (0.42 if prev == 'the' else
                     -0.4 if prev == 'not' else -0.73)
        elif w == 'even':
            if prev in {'not', 'cannot', 'or', 't'}:
                value = -1.3
            elif prev in {'a', 'an', 'the'} or prev in COPULAS:
                value = 0.0
        elif w == 'so':
            value = 0.0 if prev in COPULAS else -0.7
        elif w == 'also':
            if language == 'de':
                value = -3.0
            else:
                value = -0.6 if prev in {'and', 'but', ''} else -0.15
        elif w == 'non':
            value = -1.4 if language == 'romance' else -0.1
        elif w == 'gar':
            value = -3.8 if language == 'de' else 0.0
        elif w == 'immer' and language != 'de':
            value = -0.1
    if w in GERMAN_GRAMMAR:
        language = 'de'
    elif w in ROMANCE_GRAMMAR:
        language = 'romance'
    elif w in ENGLISH_GRAMMAR:
        language = 'en'
    return (doc, word, language), float(value)

