"""Candidate v6: Portuguese clitic pronouns 'se', 'te', 'nos' (and 'Se') read in Portuguese text;
plus document-start token classes."""
READS = ()
PT_WORDS = {"não", "são", "você", "também", "isso", "uma", "dos", "das", "para", "com",
            "mais", "como", "mas", "está", "ção", "ele", "ela", "pelo", "pela", "muito",
            "os", "um", "é", "que", "de", "do", "da", "em", "ao", "se", "eu", "nós"}
