def start_value(s):
    if s[:1].isdigit() or s[:1].isspace() or s[:1] == "":
        return -0.2
    if s[:1] == " ":
        return -0.1
    if s[0].isalpha():
        return 0.17
    return 0.05

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return (0, 0, prefix.document_ids[-1]), start_value(s)
    pt_hits, words, doc = (0, 0, None) if carry is None else carry
    if prefix.document_ids[-1] != doc:
        pt_hits, words = 0, 0
