        value = 3.0
    return (pt_hits, words, prefix.document_ids[-1]), value

programs.sol:
"""A lexical detector centered on the particle and compound ending 'out'.

The preceding verb changes the response: 'find out' is nearly silent,
'carry out' is weak, and 'drop out' is strong. WordNet identifies verbal
first parts of closed compounds, including spellings split across tokens.
Out-prefixed words get smaller responses. Case and punctuation distinguish
some identifier uses. Katakana, Cyrillic and Hangul out-like syllables are
recognized through transliteration. A weaker one-token trace continues onto
selected function words; most other tokens get zero. Recent spelling and
the trace are discarded at document boundaries.
"""
import re
import regex
from functools import lru_cache
import wordnet
from anyascii import anyascii

READS = ()

# Approximate strengths of the particle in familiar phrasal verbs.
PHRASAL = {
    'find': 0.0, 'seek': -0.7, 'carry': -1.4, 'figure': -1.6,
    'cancel': -2.0, 'rule': -2.1, 'start': -1.5, 'come': -2.1,
    'spread': -2.4, 'filter': -2.2, 'get': -2.4, 'reach': -2.8,
    'set': -2.6, 'point': -2.7, 'turn': -2.7, 'check': -3.3,
    'run': -3.2, 'work': -4.8, 'miss': -6.0, 'break': -5.3,
    'roll': -7.0, 'sell': -6.6, 'hang': -5.1,
    'drop': -8.5, 'black': -8.5, 'blow': -7.5,
    'be': -2.6, 'arise': -1.9, 'let': -2.0, 'bring': -2.0,
}
# These out-compounds are less strongly detected than most verb+out nouns.
COMPOUND = {'lay': -2.0, 'time': -3.7, 'look': -2.6, 'turn': -3.1,
            'work': -4.3, 'fall': -4.3, 'hand': -2.0}
OUT_PREFIXES = {'stand': -2.6, 'dat': -2.5, 'right': -2.1,
                'age': -3.1, 'let': -1.5, 'reach': -2.2,
                'fit': -1.4, 'door': -0.7, 'ward': -0.9, 'ed': -4.8}
TRACE = {'the': 0.40, 'to': 0.46, 'a': 0.29, 'on': 0.29,
         'with': 0.10}


@lru_cache(maxsize=4096)
def forms(word):
    return (word,) + tuple(wordnet.base_forms(word))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, trace = ('', 0.0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    text = token.lower()
    word = text.strip(' ./_-')
    previous = re.search(r'([a-z]+)\s*$', tail)
    previous = previous.group(1) if previous else ''
    joined = (previous + word if text[:1].isalpha()
              and tail[-1:].isalpha() else word)
    value = trace * TRACE.get(word, 0.0)
    if word in {'out', 'outs'}:
        value = -4.0 if text[:1].isspace() else -2.4
        if text[:1].isspace():
            value = next((PHRASAL[b] for b in forms(previous)
                          if b in PHRASAL), value)
            if not previous:
                value = -2.5 if tail else -5.2
            elif previous in {'a', 'an', 'the', 'way'}:
                value = -1.8
        if text.startswith('-'):
            value = -4.4
    # Closed compounds include split spellings such as 'drop' + 'out'.
    for spelling in (word, joined):
        match = re.fullmatch(r'([a-z]+)outs?', spelling)
        if not match:
            continue
        stem = match.group(1)
        if stem in COMPOUND:
            value = COMPOUND[stem]
            break
        if 'verb' in wordnet.parts_of_speech(stem):
            value = -5.8
            break
        if word in {'out', 'outs'} and wordnet.parts_of_speech(spelling):
            value = -0.4
    family = word if word.startswith('out') else joined
    if family.startswith('out') and family not in {'out', 'outs'}:
        value = next((v for s, v in OUT_PREFIXES.items()
                      if family[3:].startswith(s)), -0.15)
    if word in {'about', 'without', 'throughout'} or joined in {
        'about', 'without', 'throughout', 'partout',
    }:
        value = 0.0
    if text.startswith('.') and word in {'out', 'outs'}:
        value = 0.0
    if text.startswith('_') and word in {'out', 'outs'}:
        value = -0.7
    if word in {'out', 'outs'} and token.strip().isupper():
        value *= 0.65
    elif token == 'Out' and previous:
        value = -1.7
    # Borrowed spellings of the out syllable, restricted by writing system.
    if not text.isascii():
        roman = anyascii((tail + text)[-12:]).lower()
        for script, sound in (('Katakana', 'auto'), ('Cyrillic', 'aut'),
                              ('Hangul', 'aus')):
            if roman.endswith(sound) and regex.search(
                rf'\p{{Script={script}}}$', text
            ):
                value = -6.5
    new_trace = value if word in {'out', 'outs'} else 0.0
    return (doc, (tail + text)[-64:], new_trace), float(value)

"""Approximate word-completion signal, with separate document-start behavior.

A joined fragment gets a small positive response when the completed word is
more familiar than the new piece alone. A familiar standalone word joined
to a longer prefix gets a small negative response. Word frequencies are
fixed corpus counts, not a table of model tokens. Short initial words are
usually negative; initial Python 'from' and the initial number 12 are exceptions.
"""
from functools import lru_cache
from math import log10
import re
import unicodedata
from wordfreq import get_frequency_dict

READS = ()

@lru_cache(maxsize=None)
def lexicon(language):
    return get_frequency_dict(language)

@lru_cache(maxsize=100000)
def familiar(word, language='en'):
    f = lexicon(language).get(word.casefold(), 0.0)
    return max(0.0, 9 + log10(f)) if f else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, '', '')
    _, position, word, last = carry
    s = prefix.token_strings[-1]
    match = re.match(r'[^\W\d_]+', s)
    piece = match.group() if match else ''
    joining = bool(word and piece)
    language = 'en'
    if piece:
        name = unicodedata.name(piece[0], '')
        if 'CJK' in name:
            language = 'zh'
            tail = re.search(r'[^\W\d_]+$', last)
            word = tail.group() if tail else ''
        elif 'HANGUL' in name:
            language = 'ko'
        elif 'CYRILLIC' in name:
            language = 'ru'
    whole = word + piece if joining else piece
    whole_freq = familiar(whole, language)
    piece_freq = familiar(piece, language)
    clean = s.strip()
    length = len(clean)
    if position == 0:
        if s == 'from':
            value = 0.907
        elif length <= 4:
            if s.isalpha():
                value = -0.386 if length <= 1 else -0.251
            else:
                value = -0.128 if familiar(clean) <= 6.55 else -0.053
        elif s[:1].isspace():
            value = -0.083 if length <= 6 else -0.022
        else:
            value = 0.011 if s.isalpha() else 0.117
    elif position == 1 and last == '1' and s == '2':
        value = 1.83
    elif whole_freq - piece_freq > 0.15:
        if whole_freq > 4.15:
            value = 0.078 if clean.isascii() and clean.isalpha() else 0.037
        else:
            value = 0.027 if len(word) <= 2 else 0.008
    elif len(word) > 2:
        value = -0.007 if piece_freq > 4.53 else 0.001
    else:
        value = 0.012 if joining else 0.003
    tail = re.search(r'[^\W\d_]+$', s)
    new_word = tail.group() if tail else ''
    if s.isalpha():
        new_word = word + s
    return (document, position + 1, new_word[-60:], s), value

"""Approximate a college/colleg- spelling detector, not education in general.

Whole college words, split-token completions, and short cognate endings get
positive responses. Accent removal and transliteration share the stem rules
across scripts. We also recognize 'College of', academic .edu addresses,
Course Hero, and the Chinese word for college. Other responses are left at
