"""A small approximation of contextual English and delimiter responses.

Demonstratives after prepositions and exemplifying phrases lean negative;
'also' leans positive. Delimiters become more positive on longer lines.
There are also fixed responses for a few formatting markers, including the
colon in a document-opening 'Title:' header. Other tokens predict zero.
This captures regularities, not the component's arbitrary lexical variation.
"""

READS = ()
PREPOSITIONS = set(
    'in on at to for from with within without into onto upon under over '
    'through between among of by about as than after before during around '
    'behind toward towards'.split()
)
COMMON_RELATIONS = set('in on at to for from with within into onto'.split())
CONJUNCTIONS = {'and', 'but', 'or', 'nor', 'yet', 'so'}
PUNCTUATION = {
    ',': -0.013,
    '.': -0.019,
    ':': -0.009,
    ';': -0.024,
    '?': -0.037,
    '_': -0.035,
}


def activation(text, previous, line_length, position):
    word = text.strip()
    length = min(line_length, 160) / 64
    if position == 1 and previous == 'Title' and word == ':':
        return -1.81
    if '\n' in text:
        if word.endswith(('.', '。')):
            return -0.008 + 0.061 * length
        if word.endswith((';', ')', ']')):
            return 0.014 + 0.034 * length
        if '`' in word:
            return 0.054 + 0.034 * length
        return -0.011 + 0.034 * length
    if word in {'this', 'that', 'these', 'those'} and text.startswith(' '):
        plural = word in {'these', 'those'}
        value = -0.021 if plural else 0.011
        if previous in PREPOSITIONS:
            value -= 0.057 if plural else 0.048
            if previous in COMMON_RELATIONS:
                value -= 0.092 if plural else 0.047
        if previous in CONJUNCTIONS:
            value += 0.080 if plural else -0.006
        return value
    lower = word.lower()
    if lower == 'also':
        return 0.087 + 0.047 * length - (
            0.080 if previous.lower() in CONJUNCTIONS else 0.0
        )
    if lower == 'often':
        return -0.096
    if lower == 'still':
        return -0.081
    if lower in {'then', 'again'}:
        return -0.040
    if lower in {'example', 'instance'}:
        if previous.lower() == 'for':
            return -0.124 + 0.013 * length
        return 0.070 if lower == 'instance' else 0.0
    if word in PUNCTUATION:
        value = PUNCTUATION[word] + 0.014 * length
        if word == '.':
            value += 0.011 * length
        if word in {',', '.', ':'}:
            value -= 0.081 / (1 + position / 3)
        return value
    if text.startswith('\\'):
        return -0.019
    if word == '://':
        return 0.070
    if text == '<think>':
        return 0.118
    if text == '<|im_end|>':
        return 0.026
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line_length, position = '', 0, 0
    else:
        _, previous, line_length, position = carry
    text = prefix.token_strings[-1]
    value = activation(text, previous, line_length, position)
    line_length = 0 if '\n' in text else line_length + 1
    return (doc, text.strip(), line_length, position + 1), float(value)

