"""Layer 1, MLP down_proj component 4764: a weak, lexical neuron.

What it is: the component reads almost only the MLP hidden unit 4764 of layer 1
(its input direction is dominated by that one unit), so its activation is that unit's
value times a fixed scale. The unit is mostly driven by the *current word*, not by
its neighbours, and its values are idiosyncratic. Most of its variance is spread over
a long tail of individual words, so no short list captures much of it.

What this program predicts (plain rules, values are rough average activations):
  * the first token of each document (after <|endoftext|> or at the start of a row)
    is negative (about -0.05), since at that point the unit only sees the token itself;
  * the adverb "also" is clearly positive (about +0.12);
  * a sentence-final period followed by a newline is mildly positive (about +0.03);
  * the demonstratives/object pronouns "these", "those", "them", "him" are negative
    (about -0.06), as is a small set of adverbs and "example" ("still", "often",
    "again", "then", "just", "even", "well", "example") (about -0.07);
  * the common conjunctions and prepositions ("of", "and", "with", "at", "but", "because",
    "while") are slightly positive (about +0.02);
  * everything else is predicted as 0.

Main idea: a few concept-level word classes explain only about 1 to 2 percent of the
variance on held-out text. A full per-word table explains about 15 percent, but that
table is a list of arbitrary token ids, so it is not included here.
"""

READS = ()

ALSO = {" also", " Also", "also", "Also"}
SENTENCE_END_NEWLINE = {".\n", ".\n\n"}
DEMONSTRATIVE_OBJECT = {" these", " those", " them", " him"}
NEGATIVE_ADVERBS = {" still", " often", " again", " then", " Then", " just", " even", " well", " example"}
CONJUNCTIONS_PREPOSITIONS = {" of", " and", " with", " at", " but", " because", " while"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, -0.05
    if token in ALSO:
        return carry, 0.12
    if token in SENTENCE_END_NEWLINE:
        return carry, 0.03
    if token in DEMONSTRATIVE_OBJECT or token in NEGATIVE_ADVERBS:
        return carry, -0.06
    if token in CONJUNCTIONS_PREPOSITIONS:
        return carry, 0.02
    return carry, 0.0

"""Word-internal pieces and the first token of each document.

A word piece is a token with no leading space, made only of letters, that
follows another letter token in the same document. Greek word pieces are
positive; short Latin pieces (1-2 letters) are slightly positive, longer Latin
pieces slightly negative. The first token of a document is negative. Runs of
middle dots (leader lines) are strongly negative.
"""
import unicodedata

READS = ()


def _letters(s):
    s = s.strip()
    return len(s) > 0 and all(ch.isalpha() for ch in s)


def _script(s):
    names = [unicodedata.name(ch, "") for ch in s if ch.isalpha()]
    return names[0].split()[0] if names else ""


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.35
    if cur and set(cur) <= set("·"):
        return None, -1.6
    prev = prefix.token_strings[-2]
    if cur.startswith(" ") or not (_letters(cur) and _letters(prev)):
        return None, 0.0
    if _script(cur) == "GREEK":
        return None, 0.5
    if _script(cur) == "LATIN":
        return None, 0.07 if len(cur) <= 2 else -0.03
    return None, 0.0

"""Activation of one MLP direction in layer 1, read as a word detector.

It fires on words meaning "around / about / surrounding":
- the English "around" (strongest, about 5.5 to 6), and "round" more weakly;
- the article right after "around" or "round" ("around the world", "round the corner"),
  about 2.5, since the component stays on through the phrase;
- the Germanic preposition "um" / Dutch "om" (German "um", "darum", "herum"; Dutch
  "om te"), which means "around / about / for" and is strong only inside German or
  Dutch text. "um" in Portuguese, where it is an article, stays near zero;
- words for surrounding space or enclosing ("surrounding", "circum-", "encompass",
  "area", "rounded"), weakly.
Everything else predicts 0.

German/Dutch text is detected from the current document so far: at least three
common German or Dutch function words (die, und, nicht, het, een, ...) before this token.
"""

READS = ()

GERMANIC = {" die", " der", " und", " sie", " den", " dem", " des", " ein", " eine",
            " nicht", " mit", " von", " zu", " sich", " auf", " ihre", " das", " het",
            " een", " dat", " niet", " van", " voor", " te", " ich", " wir", " oder", " auch"}

AROUND = {" around": 5.5, "around": 5.8, " Around": 6.0, "Around": 6.0, " round": 1.0}
AFTER_AROUND = {" the": 2.5, " a": 0.5, " an": 0.5}
SURROUND = {" surrounding": 2.0, " circum": 1.5, " encompass": 1.1, " area": 0.7,
            " Area": 0.6, " rounded": 1.5}
GERMANIC_PREP = {" um": 5.5, " Um": 5.5, " om": 5.5}
GERMANIC_PIECE = {"um": 2.0, "rum": 2.5, "orum": 1.6}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0)
    _, count = carry
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    germanic = count >= 3
    if tok in AROUND:
        value = AROUND[tok]
    elif prev in (" around", "around", " Around", " round") and tok in AFTER_AROUND:
        value = AFTER_AROUND[tok]
    elif tok in GERMANIC_PREP:
        value = GERMANIC_PREP[tok] if germanic else 1.0
    elif tok in GERMANIC_PIECE:
        value = GERMANIC_PIECE[tok] if germanic else 0.5
    else:
        value = SURROUND.get(tok, 0.0)
    if tok in GERMANIC:
        count += 1
    return (doc, count), value

