"""Predict negative responses to short oc/ok-like spelling fragments.

ASCII transliteration extends the same spelling tests to other scripts.
On Han tokens, suppress the cross-token letter-junction rule.
Also recognize c/k/q at the start of a token after a token ending in o,
and keep a small after-response on the next alphabetic continuation.
All state resets at a document boundary. Long tokens are downweighted.
"""
from functools import lru_cache
import regex as re
import unicodedata
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=65536)
def spelling(token):
    token = unicodedata.normalize('NFKC', token)
    han = bool(re.match(r'\p{Script=Han}', token))
    return anyascii(token).lower(), token.isascii(), han


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text, ascii_only, han = spelling(prefix.token_strings[-1])
    n = len(text)
    if text.startswith('oc'):
        value = -2.0 if n <= 4 else -0.55
    elif previous.endswith('o') and text[:1] in ('c', 'k', 'q'):
        if han:
            value = 0.0
        elif ascii_only:
            value = -2.9 if n <= 3 else -1.2
        elif n == 1:
            value = -4.0
        elif n == 2:
            value = -1.5
        else:
            value = -0.8 if n == 3 else 0.0
    elif text.startswith('ok'):
        value = -1.6 if n <= 3 else -1.1
    elif re.search(r'o[ckq]', text):
        value = -1.0 if n <= 3 else (-0.5 if n == 4 else -0.1)
    elif text[:1].isalpha() and previous.startswith(('oc', 'ok')):
        value = -0.7
    else:
        value = 0.0
    return (doc, text), value

