            else:
                value = 0.7 if not s.strip('\t') else 0.55
            ending = previous.rstrip()
            if ending.endswith((':', '{', '[')):
                value -= 0.75
            if re.match(r'^\s*\d+\t', previous):
                value += 0.4
            if first:
                value -= 0.6
            elif not previous.strip():
                value -= 0.25
        elif not line.strip(' \t\r'):
            value = -0.05 if '\t' not in s else 0.0
        elif s == '\t':
            value = -0.1
        elif len(s) > 1:
            value = 0.03
    if first and s == 'Title':
        value = -2.31
    elif title_pending and s == ':':
        value = 21.2
    pieces = (line + s).split('\n')
    if len(pieces) > 1:
        previous = pieces[-2]
    carry = (doc, pieces[-1][-300:], previous, first and s == 'Title')
    return carry, value

