"""Line-start indentation detector for layers.1.mlp.down_proj : 4774.

The component writes into the residual stream when a line of code opens with an
indentation run: a token made only of spaces (or only of tabs) that comes right
after a newline. Its size depends on the indentation width in spaces:

- 2 spaces is the strongest (about 1.4), 4 spaces is about 1.2, 3 spaces about 0.9;
- 1 space and 8 spaces are about 0.7 to 0.8, 5 to 7 spaces about 0.6 to 0.7;
- 9 to 16 spaces are weak (about 0.4), and 17 or more are essentially off;
- tab-only indents are about 0.4.

Everything else (including indentation in the middle of a line) predicts 0.
There is no state beyond the current token and the one before it.
"""

READS = ()

# Activation at a line-start indent, by its width in spaces.
SPACES = {1: 0.7, 2: 1.4, 3: 0.9, 4: 1.2, 5: 0.6, 6: 0.6, 7: 0.7, 8: 0.8}
TAB_INDENT = 0.4


def indent_response(token: str, after_newline: bool) -> float:
    if not after_newline or not token:
        return 0.0
    if set(token) == {"\t"}:
        return TAB_INDENT
    if set(token) != {" "}:
        return 0.0
    width = len(token)
    if width in SPACES:
        return SPACES[width]
    return 0.4 if width <= 16 else 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
