"""Two local spelling patterns approximate this early-layer component.

A letter-initial token is boosted after a short piece containing n,
including transliterated alphabetic and katakana spelling. Capitalization,
vowel-initial continuations and Arabic script strengthen the response;
another n in the continuation weakens it. A smaller trace can survive
one intervening word piece.
Han readings and hiragana do not supply this n cue.

There is also a strong response to a digit following 9, sometimes across a
decimal point. Middle-valued digits respond most; repeated 9s weaken it.
The state resets at document boundaries. These are approximate spelling
rules, not a semantic model.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()
N_GAIN = 1.2  # A training-calibrated gain for the spelling cue.
EXCLUDED = regex.compile(r'[\p{Script=Han}\p{Script=Hiragana}]')
VOWELS = frozenset("aeiou")
ARABIC = regex.compile(r'\p{Script=Arabic}')


@lru_cache(maxsize=32768)
def letters(text):
    roman = anyascii(EXCLUDED.sub('', text)).lower()
    return ''.join(c for c in roman if c.isalpha())


def short_piece(spelling):
    return 1 / (1 + max(0, len(spelling) - 2) ** 2 / 8)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = older = ''
    else:
        _, previous, older = carry
    text = prefix.token_strings[-1]
    current_letters = letters(text)
    previous_letters = letters(previous)
    older_letters = letters(older)
    value = 0.004

    if text[:1].isalpha():
        length_gain = 1 / (1 + 0.3 * max(0, len(current_letters) - 3))
        has_n = 'n' in current_letters
        if 'n' in previous_letters:
            gain = 0.12 if has_n else 0.56
            if not has_n:
                gain += 0.23 * previous.strip()[:1].isupper()
                gain += 0.61 * bool(ARABIC.search(previous))
                gain += 0.19 * (current_letters[:1] in VOWELS)
                gain -= 0.14 * previous.isalpha()
            value += N_GAIN * gain * short_piece(previous_letters) * length_gain
        if previous.isalpha() and 'n' in older_letters and not has_n:
            remaining = max(0, 1 - len(previous_letters) / 6)
            trace = remaining * short_piece(older_letters) * length_gain
            value += N_GAIN * 0.61 * trace
        if current_letters.endswith('n'):
            value -= 0.02
    elif 'n' in current_letters:
        value -= 0.015

    if len(text) == 1 and text in '0123456789':
        digit = int(text)
        if previous == '9':
            # A smooth response, largest for middle-valued digits.
            value = 0.58 + 0.39 * digit - 0.039 * digit ** 2
            if digit == 9:
                value -= 0.62
            if older == '9':
                value -= 0.35 + 0.07 * digit
        elif previous == '.' and older == '9':
            value = 1.02
        elif digit == 9:
            value = -0.035
    return (doc, text, previous), value

