import codecs
import re
import string
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiouyаеёиоуыэюяαεηιουω'
O_INITIALS = frozenset('oоοœø')


def vowel(ch):
    return bool(ch) and unicodedata.normalize('NFD', ch).lower()[0] in VOWELS


@lru_cache(maxsize=8192)
def word_info(s):
    w = s.lstrip(string.whitespace + string.punctuation)
    first = unicodedata.normalize('NFD', w[:1]).lower()[:1]
    lang = 'ru' if first == 'о' else 'el' if first == 'ο' else 'en'
    frequency = zipf_frequency(w.lower(), lang) if first in O_INITIALS else 0.0
    return w, first, frequency


def zero(prev, history):
    if not prev:
        return 0.15
    ch = prev[-1]
    if ch.isdigit():
        return -0.05
    recent = history[-60:]
    density = sum(c.isdigit() for c in recent) / max(1, len(recent))
    run = re.search(r'\d+$', history[:-1])
