    r'\b(?:in|of|on|from|during|until|since|by|born|died|between|copyright|'
    r'year|updated|published|released|joined|edited|retrieved|accessed|'
    r'january|february|march|april|may|june|july|august|september|'
    r'october|november|december)\b', re.I)


