"""layers.1.mlp.down_proj:4779, a readable approximation.

This component fires in two situations.

1. The first token of a document (or of a packed row, which the model also reads
   as a fresh start): the model sees nothing before it, so the value depends on
   the token alone. The approximation sorts those tokens into rough classes:
   the chat-template token <|im_start|> is strongest, then newlines, punctuation
   and capitalised words; words with a leading space are middling; lowercase
   words and digits are near zero or slightly negative.

2. The second digit of a number that starts with 1, 2 or 3 (years, mainly):
   "19" in 1900s years is strongest, "20" in 2000s next, and a few other
   1x / 2x / 3x pairs are weaker. Digits inside a longer number are ignored.

Everything else predicts 0. The class values are rough means from a few hundred
training rows, not fitted to the eval rows.
"""

READS = ()

YEAR_PAIRS = {("1", "9"): 1.1, ("2", "0"): 0.8, ("1", "1"): 0.4, ("2", "1"): 0.4, ("3", "0"): 0.4, ("3", "1"): 0.4}


def doc_start_value(s):
    """Activation at the first token of a document, from the token's string."""
    if s == "<|im_start|>":
        return 3.3
    if s.strip() == "" or not any(c.isalnum() for c in s):
        return 1.5  # newlines, punctuation, symbols
    if s.isdigit():
        return -0.2
    if s[:1].isupper():
        return 1.5  # capitalised word
    if s.startswith(" "):
        return 0.6  # word with a leading space
    return 0.2  # lowercase word, no space


def step(carry, prefix, upstream):
    t = prefix.position
    s = prefix.token_strings
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, doc_start_value(s[-1])
    if t >= 2 and s[-1].isdigit() and s[-2].isdigit() and not s[-3].isdigit():
        return None, YEAR_PAIRS.get((s[-2], s[-1]), 0.0)
    return None, 0.0

"""layers.1.mlp.down_proj:4780 -- fires on the first word of a predicate.

Plain-language rule. The component reads the word right after a linking word: a
copula ("is", "are", "was", "were", "be", "been", "'s", "not") or an equals sign ("=").
Or it reads the word after one determiner that follows the copula ("is not the").
It fires there when that word is
  * an article ("a", "an", "the")        -> about 0.9, about 1.3 when the subject is
                                            "it", "this" or "that" ("it is a", "this is the")
  * a predicate word ("case", "about", "question", "worth", "enough", "what", "one",
    "same", ...)                          -> about 1.0
  * the digit "0" or "1" right after "=" (as in "x = 0")  -> about 1.1
Multiplied by 1.4 when a determiner sits between the copula and the word ("is not the case").
It also fires on "of" in "a matter of", "the result of", "an instance of" (about 0.8).
It is silent after "there is/are" and "what is", and on participle or passive complements
("is being", "is put"). Everywhere else it is about 0.
Fitted on 3072 training rows: variance explained about 0.21 on eval.
"""

READS = ()

COPULA = {" is", " are", " was", " were", " be", " been", " am", " being", " not", "'s", "’s"}
EQUALS = {"=", " =", ")=", "≠", "≈"}
LINK = COPULA | EQUALS | {"是"}
DET = {" not", " the", " a", " an", " just", " all", " also", " still", " really", " very",
       " always", " often", " only", " that", " this", " so", " quite", " one", " such", " no",
       " my", " your", " our", " his", " her", " its", " their", " it"}
ARTICLES = {" a", " an", " the"}
SUBJECT_IT = {" it", " It", " this", " This", " that", " That"}
DIGITS = {"0", "1"}
PREDICATE_WORDS = {" case", " about", " question", " matter", " what", " worth", " enough",
                   " one", " same", " something", " okay", " zero", " fine", " acceptable",
                   " wrong", " good", " part", " all", " just", " new", " most", " another",
                   " my", " your", " our", " his", " her", " their", " this", " that", " it"}
PREDICATE_NOUNS = {" matter", " instance", " result", " part"}
THERE = {" there", " There", " What", " what"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) >= 2 else ""
    prev2 = toks[-3] if len(toks) >= 3 else ""
    prev3 = toks[-4] if len(toks) >= 4 else ""

    # "of" closing a predicate phrase: "a matter of", "the result of"
    if cur == " of" and prev in PREDICATE_NOUNS:
        return None, 0.8

    # the link word sits right before the token, or before one determiner ("is not the")
    if prev in LINK:
        link, far = prev, prev2
        strength = 1.0
    elif prev in DET and prev2 in LINK:
        link, far = prev2, prev3
        strength = 1.4
    else:
        return None, 0.0
    if far in THERE:
        return None, 0.0

    if link in EQUALS and cur in DIGITS:
        return None, 1.1
    if cur in ARTICLES:
        if far in SUBJECT_IT:
            return None, 1.3 * strength
        return None, 0.9 * strength
    if cur in PREDICATE_WORDS:
        return None, 1.0 * strength
    return None, 0.0

