def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, tail, repeated, count = '', '', token, 0
        cr_count, cr_run = 0, 0
    else:
        _, previous, tail, repeated, count, cr_count, cr_run = carry
        if token != repeated:
            repeated = None

    cr_count += token == '\r'
    cr_run = cr_run + 1 if token == '\r' else 0
    value = 0.0
    if count == 0:
        word = token.strip()
        value = -0.18
        if word.isalpha():
            if token[:1].isspace():
                value = -0.23
            elif word.isupper():
                value = 0.09
            elif word.istitle():
                value = -0.09
            elif word.islower():
                value = -0.03
        elif token.isdigit():
            value = -0.09
        if token == ' .':
            value = -2.96
        elif token == '//\n':
            value = 5.76
        elif token in ('//', '/*', '/*\n'):
            value = -1.04
    elif count == 1 and previous == 'Title' and token == ':':
        value = -2.59

    if token == '\x00':
        if not count:
            value = -2.36
        elif previous.isspace():
            value = -0.20
        elif previous[-1:].isdigit():
            value = -0.93
        elif previous[-1:].isupper():
            value = -1.21
        elif previous[-1:].isalpha():
            value = -1.43
        else:
            value = -0.65
    elif token == '\r':
        fraction = cr_count / (count + 1)
        value = max(0.0, 6.0 * (fraction - 0.65)) * min(1.0, cr_run / 60)
        value += 0.004 * max(0, cr_run - 60)
        value = 4.75 if repeated == token else min(4.75, value)
    elif token == '··' and repeated == token:
        value = -2.15
    elif token == '5':
        if not count:
            value = -0.52
        elif tail.lower().endswith(('md', 'html', 'hdf')):
            value = 1.02
        elif previous[-1:].isascii() and previous[-1:].isalpha():
            value = 0.27
        elif previous[-1:].isspace():
            value = 0.10
        elif previous[-1:].isdigit():
            value = 0.02
        else:
            value = 0.01
    elif (count and tail.lower().endswith('fif')
          and token in ('teen', 'teenth')):
        value = 0.65 if token == 'teen' else 1.04
    elif (count and tail.lower().endswith('f')
          and token.lower() in ('ive', 'ives')):
        value = 2.26 if tail.lower().endswith('high-f') else 0.85
    elif count and token.lower().strip(' -') == 'five':
        value = 0.65 if tail.lower().endswith('high') else 0.12
    tail = (tail + token)[-12:]
    return (doc, token, tail, repeated, count + 1, cr_count, cr_run), value

"""A local spelling detector, mostly negative on vowel+i+s sequences.

Small fragments (e.g. o + is, or ais) elicit stronger responses than whole
words. Vowel+i+h has the opposite sign. Parallel rules cover a few non-Latin
spellings. Common Portuguese -ais words are excluded using word frequencies.
A word's next token retains 18% of the preceding spelling response.
"""
import re
from wordfreq import zipf_frequency

READS = ()

# Before i+s: bare 'is', 'ist'/'ish', and other continuations of 'is'.
SPLIT_IS = {
    'a': (-3.1, -3.1, -3.1),
    'e': (-5.2, -2.5, -3.2),
    'o': (-6.8, -2.4, -4.0),
    'u': (-0.7, -0.1, -0.3),
