IS_PIECES = {'a': -5.1, 'e': -4.4, 'o': -3.6, 'u': -0.6}


def response(previous, token, tail):
    s, p, tail = token.lower(), previous.lower(), tail.lower()
    joined = s and p and s[0].isalpha() and p[-1].isalpha()
    # 'Is' in a camelCase identifier begins a new word, not a diphthong.
    if token.startswith('Is'):
        joined = False
    if joined:
        if p[-1] in 'イｲ이' and s[0] in 'スズｽ스':
            return -2.5
        if p[-1] in 'ιίῖ' and s[0] in 'σς':
            return -3.2 if tail[-2:-1] in ('α', 'ο') else -0.2
        if p[-1] == 'й' and s[0] in 'сзш':
            return -3.0 if len(s) == 1 else -0.4
        if p[-1] in 'оеа' and s.startswith(('ис', 'из')):
            return -2.5
        if p[-1] in 'iíïî' and s[0] in 'szxßſ':
            if tail[-2:-1] in ('a', 'e', 'o', 'u'):
                return -3.7
            return -0.6 if s[0] == 'ſ' else -0.1
        if p[-1] == 'i' and s[0] == 'h' and len(s) <= 2:
            return 2.6 if tail[-2:-1] in ('a', 'e', 'o', 'u') else 0.0
        if p[-1] in SPLIT_IS and s.startswith('is'):
            shape = 0 if len(s) == 2 else 1 if s[2] in 'th' else 2
            return SPLIT_IS[p[-1]][shape]
        if p[-1] in SPLIT_IS and s.startswith(('iz', 'iß', 'ix', 'if')):
            return -1.1
        if p[-1] in SPLIT_IS and s.startswith('ih'):
            return 5.0

    match = re.search(r'([aeou])is', s)
    if match:
        vowel = match[1]
        word = s.strip()
        if s == match[0]:
            if vowel == 'a':
                ending = re.search(r'[^\W\d_]+$', tail + s)
                word = ending[0] if ending else s
                pt = zipf_frequency(word, 'pt')
                fr = zipf_frequency(word, 'fr')
                if len(word) > 4 and pt > max(3.0, fr + 1.5):
                    return 0.0
            return IS_PIECES[vowel]
        if word.find(match[0]) <= 2 and len(word) <= 7:
            capital = token.strip()[:1].isupper()
            if vowel == 'a':
                return -0.6
            if vowel == 'e':
                return -2.0 if capital else 0.0
            if vowel == 'o':
                return -1.5 if capital else -1.0
            return -0.1
    if any(x in s for x in ('イス', 'イズ', '이스')):
        return -2.1
    if s.strip() in ('أي', 'إي'):
        return 4.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail, last = '', '', 0.0
    else:
        _, previous, tail, last = carry
    token = prefix.token_strings[-1]
    base = response(previous, token, tail)
    continuation = (token and previous and token[0].isalpha()
                    and previous[-1].isalpha())
    value = base + (0.18 * last if continuation else 0.0)
    return (doc, token, (tail + token)[-64:], base), float(value)

"""Sparse rules for numeric and abbreviation continuations.

After a comma inside a number, predict a strong first-digit negative pulse,
a weaker second-digit response, and a small positive third-digit response.
Word frequencies estimate whether preceding prose uses decimal commas;
this strengthens the negative pulse. Lists get weaker responses.
Cyrillic all-caps fragments get negative values, strongest at split joins.
Repeated middle-dot leaders and an opening Title: field have separate rules.
Everything else is zero. State resets at document boundaries.
"""
import functools
import re
import unicodedata
from wordfreq import zipf_frequency

READS = ()
COMMA_LANGUAGES = (
    'de', 'fr', 'es', 'pt', 'it', 'nl', 'pl',
    'cs', 'da', 'sv', 'id', 'tr', 'fi',
)


@functools.lru_cache(maxsize=50000)
def locale_evidence(word):
    """Commonness in decimal-comma languages relative to English."""
    script = unicodedata.name(word[0], '')
    if 'CYRILLIC' in script:
        return 3.0
    if 'LATIN' not in script:
        return 0.0
    english = zipf_frequency(word, 'en')
    other = max(zipf_frequency(word, lang) for lang in COMMA_LANGUAGES)
    return max(-3.0, min(3.0, other - english))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, 0, '', '', 0.0, '')
    _, position, history, word, locale, previous = carry
    token = prefix.token_strings[-1]
    value = 0.0

    if len(token) == 1 and token in '0123456789':
        number = re.search(r'(\d+),(\d{0,2})$', history)
        if number:
            before, after = number.groups()
            # Confidence that the comma is a decimal separator, not code.
            strength = max(0.0, min(1.0, (locale - 2.0) / 10.0))
            if not after:
                baseline = -0.03 if len(before) == 1 else -0.55
                prior = history[:number.start()]
                if len(re.findall(r'\d,\d{3}(?=\s|[^\d])', prior)) >= 7:
                    baseline = -1.7
                value = baseline * (1.0 - strength) - 5.7 * strength
            elif len(after) == 1:
                value = 0.05 - 2.2 * strength
            else:
                value = 0.14

    if (token.isalpha() and token.isupper()
            and 'CYRILLIC' in unicodedata.name(token[0], '')):
        prev = previous.strip()
        value = -0.1
        if prev.isupper():
            if previous[:1].isspace():
                value = -3.4
            elif len(token) == 1 and len(prev) == 1:
                value = -1.8
        elif not prev:
            value = -0.23

    if len(token) >= 2 and set(token) == {'·'}:
        value = -1.76
    if position == 1 and previous == 'Title' and token == ':':
        value = 7.8

    # Only completed words inform subsequent tokens' locale estimate.
    for char in token:
        if char.isalpha():
            word = (word + char.lower())[-60:]
        else:
            if len(word) > 1:
                locale = 0.9 * locale + locale_evidence(word)
            word = ''
    history = (history + token)[-180:]
    carry = (document, position + 1, history, word, locale, token)
    return carry, float(value)

"""Sparse lexical approximation of an early MLP feature.

The strongest rules distinguish mathematical delta/mu from Greek prose,
Chinese negated completeness and boundlessness, and source-file headers.
Other rules handle numeric/punctuation starts and split Unicode symbols.
Unmatched positions return zero: the component's many small lexical effects
are not reproduced.
"""
import re
import regex

READS = ()

# A context consisting entirely of one digit has the same value as its start.
DIGIT_START = (0.489, 0.132, 0.317, -0.330, 0.077,
               0.214, 0.287, 0.036, 0.274, -0.085)
# Full, complete, same, fitting (the last as in 不切实际, impractical).
NEGATED_FULL_OR_SAME = {'全', '完全', '相同', '切'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        tail, same, initial = b'', True, raw
    else:
        _, tail, same, initial = carry
        same = same and raw == initial
    before = tail.decode('utf-8', 'ignore')
    joined = tail + raw
    text = joined.decode('utf-8', 'ignore')
    value = 0.0

    if same and token.isascii() and len(token) == 1 and token.isdigit():
        value = DIGIT_START[int(token)]
    if same and token == '\r':
        value = 2.33
    if same:
        if token == '//\n':
            value = 3.77
        elif token.startswith('#') and set(token) == {'#'}:
            value = max(0.05, 0.83 - 0.22 * max(0, len(token) - 2))
        elif token in {'#include', '/*'}:
            value = 0.99
        elif token == '/*\n':
            value = 0.55
        elif token.strip() in {'"', '“'}:
            value = -0.49 if token.startswith(' ') else -1.27
        elif token.strip() in {'(', ')'}:
            value = 0.39 if token.startswith(' ') else 0.60
        elif token == '.':
            value = 0.41
        elif token in {',', ':', ';'}:
            value = 0.17
        elif token == 'package':
            value = 1.03
        elif token == 'namespace':
            value = 1.98

    # These source metadata tags are split by the tokenizer.
    if text.endswith('<reponame'):
        value = -2.11
    elif text.endswith('<gh_stars'):
        value = -1.61
    elif text.endswith('<filename'):
        value = -2.06 if text == '<filename' else -0.20
    elif text == '{[':
        value = 1.60
    elif text == 'Title:':
        value = 1.24
    elif token == ' by' and before.rstrip().endswith('Created'):
        value = -0.36

    # Isolated mathematical letters, weakened by recent repetition.
    # Runs of Greek letters instead indicate Greek prose.
    symbol = token.strip()
    mathematical = symbol in {'Δ', 'μ'} or (
        symbol == 'Delta' and before.endswith('\\'))
    if mathematical:
        if not regex.search(r'\p{Greek}{3,}', before[-150:]):
            if symbol == 'μ':
                nmu = before.count('μ')
                unit = bool(re.search(r'\d[\d .]*$', before[-16:]))
                value = (0.45 if unit else 0.65) / (1 + 0.25 * nmu)
            else:
                ndelta = before.count('Δ') + before.count('\\Delta')
                value = 0.80 / (1 + 0.30 * ndelta)
    if symbol in NEGATED_FULL_OR_SAME and before.endswith('不'):
        value = -0.95
    elif symbol == '无限':
        value = -0.68

    # A byte may identify a symbol before that symbol is fully tokenized.
    if raw == b'\x9a' and (tail.endswith(b'\xe2') or
                             tail.endswith(b'\xf0\x9f')):
        value = -1.25  # miscellaneous-symbol / transport-emoji prefix
    elif raw == b'\x8a' and tail.endswith(b'\xe2\x80'):
        value = -0.65  # hair space
    elif raw == b'\x86' and text[-1:] in {'ⅆ', '⨆', '⋆', '\u0306'}:
        value = -1.50
    elif raw == b'\xaa' and tail.endswith(b'\xe7'):
        value = 1.05  # prefix shared by cave-radical Han characters
    elif raw == b'\x93' and tail.endswith(b'\xf0\x9d'):
        value = 1.0   # mathematical script alphabet prefix

    return (doc, joined[-200:], same, initial), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:4784 - a weak, mostly document-start feature.

Plain-language summary: this component is nearly silent inside documents. Its
activation is large only at the first token of a document (the first token after
<|endoftext|>, or the first token of a row), and there it depends on which token
it is, not on context. The program therefore:
  * at a document start, predicts a value by the kind of token that opens it:
    C/Python-style or markup starts ('#', '##', '#include', 'package', '/*',
    '(', ')', ' =', digits) get a positive value; English prose openers and
    quotes ('This', 'As', 'An', 'A', ' a', '"', '“', 'theorem') get a negative
    value; a carriage return '\r' or a '//\n' opener gets a large value;
    everything else gets a small positive baseline;
  * everywhere else predicts 0 (the bulk of the activation is diffuse and not
    captured by any simple rule).
Measured on fresh training rows this explains about 5% of the variance; the
rules were chosen from the data, so their exact values are approximate.
"""
READS = ()

CODE_START = {"#", "##", "###", "#include", "#!/", "package", "/*", "/*\n",
              "(", ")", " =", " {\n", "0", "2", "3", "."}
PROSE_START = {'"', "“", ' "', "This", "As", "An", "A", "On", "Welcome",
               "theorem", " a", " an", "St", "const", "   "}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if prefix.position == 0:
        new_doc = True
    else:
        new_doc = prefix.document_ids[-1] != prefix.document_ids[-2]
    if not new_doc:
        return carry, 0.0
    if s == "//\n":
        return carry, 3.76
    if s == "\r":
        return carry, 2.3
    if s in CODE_START:
        return carry, 0.7
    if s in PROSE_START:
        return carry, -0.6
    return carry, 0.15

programs.sol:
"""Document-onset pulse, strongest for plausible document-opening tokens.

The first token (or an initial run of the same token) gets a large positive
value. English word frequency, leading spaces, script, and source-file opening
syntax adjust its size. Smaller responses cover escaped/numbered indentation,
first occurrences of indentation shapes, blank lines, and spellings of the
United States. Ordinary text is near zero.
These are surface-form approximations, not a simulation of the MLP.
"""
import math
import unicodedata
from wordfreq import zipf_frequency

READS = ()
IMPORT_WORDS = {'import', 'from', 'package', 'using', 'use'}
DECLARATIONS = {'public', 'private', 'class', 'def', 'function', 'void', 'test'}


def onset(s):
    word = s.strip()
    if s == '<|endoftext|>':
        return 18.5
    if s.startswith('<|'):
        return 5.5
    if s.isspace():
        if s == '\t' or s == '\r\n':
            return 13.7
        if s.startswith(' '):
            return 3.7 if '\n' in s else 4.2 + 1.8 * math.log(len(s))
        return 7.5
    if not s.startswith(' '):
        if word in IMPORT_WORDS:
            return 16.0
        if word in DECLARATIONS:
            return 13.0
        if s.startswith(('/*', '//', '#!', '#include', '"""')):
            return 12.0
        if s.startswith('<?') or s.startswith('{'):
            return 10.3
        if s.startswith('#'):
            return 8.5
        if s.startswith('\\'):
            return 11.0
    if s.isascii():
        if word.isalpha():
            freq = zipf_frequency(word.lower(), 'en')
            if s.startswith(' '):
                return 1.55 + 0.60 * freq
            if word[0].isupper():
                return 4.3 + 0.75 * freq
            return 3.1 + 0.90 * freq
        if s.startswith(' '):
            return 4.7
        if word.isdigit():
            return 6.1
        return 3.8 if s[:1] in '.:)]' else 5.6
    first = word[:1]
    name = unicodedata.name(first, '') if first else ''
    if s.startswith(' '):
        return 2.8
    if 'HIRAGANA' in name or 'KATAKANA' in name:
        return 2.3
    if 'CJK' in name or 'HANGUL' in name:
        return 4.4
    if 'CYRILLIC' in name:
        return 6.3 if first.isupper() else 4.3
    return 3.2


def formatting(s, tail, novel):
    spaces, tabs = s.count(' '), s.count('\t')
    # Literal escaped line breaks and numbered source-code gutters.
    if tail.endswith('\\n') and '\n' not in s:
        return min(2.1, 1.25 + 0.20 * math.log(max(1, len(s))))
    if tabs and tail[-1:].isdigit() and '\n' not in s:
        return min(2.7, 0.65 + 0.58 * math.log1p(spaces)
                   + math.log(tabs))
    if '\n' in s:
        if (spaces or tabs) and (tail.endswith('\n') or s.startswith('\n')):
            return 0.9
        return 0.0
    if tail.rsplit('\n', 1)[-1].strip() in {'//', '#', '|'}:
        return 1.2 + 0.15 * math.log(max(1, len(s)))
    # A newly encountered indentation token gets a larger response.
    if tail.endswith('\n'):
        if s == ' ':
            return 0.9 if novel else 0.45
        if spaces >= 4 and spaces % 2 == 0 and not tabs:
            return 1.3 if novel else 0.3
        if not novel:
            return 0.02
        return 0.75 / tabs if tabs else 1.0 / (1.0 + spaces / 6.0)
    if s.count('\xa0') >= 2:
        return 0.7
    return -0.4 if s == '\r' else 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    first = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if first:
        value = onset(s)
        return (prefix.token_ids[-1], value, True, s[-64:], {s}), value
    opening, pulse, repeating, tail, seen_space = carry
    repeating = repeating and prefix.token_ids[-1] == opening
    value = pulse if repeating else 0.0
    if not repeating:
        if s.isspace():
            value = formatting(s, tail, s not in seen_space)
            seen_space.add(s)
        elif s.strip().lower() == 'states' and tail.lower().endswith('united'):
            value = 1.1
        elif s == '.S' and tail.endswith('U'):
            value = 1.2
        elif s.strip() in {'US', 'USA'}:
            value = 0.7
    return (opening, pulse, repeating, (tail + s)[-64:], seen_space), value

"""A small lexical mixture, not a universal semantic category.

Negative cases emphasize Chinese epidemic terms, news, situations and
updates, with Vietnamese dịch and Korean 역 as additional lexical cases.
The program also recognizes split UTF-8 characters, insertion and UI
events, repeated middle dots, title colons and the document-opening number
12. Other openings get an estimate from grammatical/formatting classes.
"""
from functools import lru_cache
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')
PRONOUNS = set('i you he she it they my your his her their'.split())
DEMONSTRATIVES = set('this that these those'.split())
QUESTIONS = set('what which where when why how who'.split())
DECLARATIONS = set('import from const let var public private def class'.split())


@lru_cache(maxsize=8192)
def lexical(text):
    word = SIMPLIFY.convert(text).strip()
    if word == '疫情':
        return -6.5
    if word in {'防疫', '疫情防控'}:
        return -3.7
    if word in {'讯', '资讯', '详情', '动态'}:
        return -2.6
    if word == '迅':  # rapid
        return -2.5
    if word in {'役', '역'}:  # service/role; Korean yeok
        return -1.7
    if word == '疾':  # illness; rapid
        return -1.3
    if word == '逆':  # contrary/reverse
        return -1.3
    if word == '剧情':  # a story's plot
        return -0.9
    if word == '服役':  # military service
        return -0.9
    if word in {'情', '态', '状态'}:
        return -0.6
    if word == '优惠':  # discounts/promotions
        return -0.7
    if word == '电信':  # telecommunications
        return -0.7
    if word == '进程':  # a process/progress
        return -0.7
    if '信息' in word:
        return -0.4
    if word in {'ịch', 'dịch'}:
        return -4.1
    if word.lower() == 'dich':
        return -0.75
    return 0.0


def opening(text):
    word = text.strip().lower()
    if text.startswith('<') and text.endswith('>'):
        return -0.08
    if text.isspace():
        return 0.05
    if text.startswith((' ', '\t')):
        return 0.12 if word.isalpha() else 0.29
    if word.isdecimal():
        return 0.15
    if word in PRONOUNS | DEMONSTRATIVES | QUESTIONS:
        return -0.32
    if word == 'we':
        return 0.71
    if word in DECLARATIONS:
        return -0.58
    if text.startswith(('#', '//')):
        return -0.37
    return 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', 0, '')
    _, tail, position, previous = carry
    text = prefix.token_strings[-1]
    joined = (tail + prefix.token_bytes[-1])[-96:]
    completed = joined.decode('utf-8', errors='ignore')
    before = tail.decode('utf-8', errors='ignore')
    word = text
    if '\ufffd' in text and completed:
        char = completed[-1]
        if joined.endswith(char.encode('utf-8')):
            word = char
    value = lexical(word)
    if word in {'态', '態'}:
        if before.endswith('事'):
            value = -6.5
        elif before.endswith(('动', '動')):
            value = -4.6
    if word == '情' and before.endswith(('战', '戰', '警', '案')):
        value = -4.3
    if joined.endswith('駅'.encode('utf-8')):
        value = -2.7
    if joined.endswith('挿'.encode('utf-8')):
        value = 2.7
    ui_actions = ('滚动', '滾動', '点击', '點擊')
    if word == '事件' and any(action in before for action in ui_actions):
        value = 1.5
    if text == ':' and previous.lower().strip() == 'title':
        value = -1.0
    if text == '··' and (previous == text or position == 0):
        value = 2.83
    if position == 0 and value == 0.0:
        value = opening(text)
    if text == '2' and previous == '1' and position == 1:
        value = 3.79
    elif text == '2' and completed == '122' and position == 2:
        value = 1.53
    return (doc, joined, position + 1, text), value

"""Carriage-return separators, weakened when they recur in a document.

CRLF blank lines give a larger response than single line endings. Indented
code and attached punctuation modulate that response. Ordinary tokens are
zero, apart from coarse document-start baselines and the strong negative
response to the colon in an initial `Title:` label. An initial run consisting
only of carriage returns has a much larger positive response. Most ordinary-token
variation is left unmodelled.
"""
import math

READS = ()


def indentation(text, spaces, tabbed, leading):
    """Keep just the current line's indentation, not its whole text."""
    for ch in text:
        if ch in '\r\n':
            spaces, tabbed, leading = 0, False, True
        elif leading:
            if ch == ' ':
                spaces += 1
            elif ch == '\t':
                tabbed = True
            else:
                leading = False
    return spaces, tabbed, leading


def initial_value(token):
    word = token.strip()
    if word.isalpha():
        if not word.isascii():
            return -0.40
        return 0.04 if token.startswith(' ') and word.islower() else -0.20
    return -0.08 if word.isdigit() else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, token, 0, 0, False, True, True)
    _, pos, first, returns, spaces, tabbed, leading, only_cr = carry
    value = 0.0

    if '\r' in token:
        line_spaces, line_tabs, _ = indentation(
            token.split('\r', 1)[0], spaces, tabbed, leading)
        body = token.strip(' \t\r\n')
        value = 0.22 - 0.035 * math.log1p(returns)
        if token.count('\r') > 1:
            value += 0.09
        if token.startswith(' '):
            value += 0.035
        value -= 0.006 * min(line_spaces, 8) + 0.04 * line_tabs
        if '{' in body or '}' in body:
            value -= 0.035
        elif body.endswith((';', ',', ':')):
            value -= 0.025
        if body == '.' or '"' in body or "'" in body:
            value += 0.035
        if '*' in body:
            value -= 0.03
        if pos == 0 and body:
            value = -0.25
    elif pos == 0:
        value = initial_value(token)
    elif pos == 1 and first == 'Title' and token == ':':
        value = -5.88

    if only_cr and token == '\r':
        value = 6.06
    only_cr = only_cr and token == '\r'
    returns += token.count('\r')
    spaces, tabbed, leading = indentation(token, spaces, tabbed, leading)
    return (doc, pos + 1, first, returns, spaces, tabbed, leading, only_cr), value

programs.haiku:
"""Layer 1 MLP down-projection, component 4789: a document-start detector.

What it does, in plain terms
- Inside ordinary text the component is nearly silent: its activation is a small,
  diffuse signal (RMS about 0.04) that depends on no simple feature, and this program
  does not model it, so it predicts 0 there.
- Its large activations come at the start of each document (the first token after a
  document boundary, or the first token of a packed row), where there is no context yet.
  There the value depends only on which token it is, and it falls into a few kinds:
    * a common English function word written with a leading space (" the", " a", " of",
      " and", " that", " to", ...): about +0.3;
    * a token in a non-Latin script (Chinese, Korean, Cyrillic, ...): about -0.36;
    * a capitalised word, a bare lower-case word, or a code-like token (identifiers,
      keywords, brackets, symbols): about -0.1 to -0.2;
    * digits: about -0.08; other punctuation: about +0.1.
- A few rare cases are very strong and token-specific: a document opening with "//\n"
  gives +7.5; a document opening with a run of carriage returns gives +6.1; a colon right
  after a document-initial "Title" gives -5.9; a repeated middle-dot run ("··" after
  "··") gives -0.67.

Why: the component explains a little under a tenth of the variance on held-out text,
mostly from the document-start rules. A token table would do no better on unseen
documents, so the word classes are the explanation.
"""
import re

READS = ()

# Common English function words, which this component likes at document start.
FUNCTION_WORDS = set(
    "the a an of and to in is that it with for as on be by at or not this are was "
    "have has had they you i he she we all some no".split()
)
# Code-like tokens: identifiers, keywords, brackets and symbols.
CODE = re.compile(
    r"[_(){};=#/<>\[\]\\]|^(import|from|def|class|return|int|const|var|let|print"
    r"|package|using|public|static|void)$"
)


def first_token_value(token):
    """Activation of a document's first token, from its kind of token alone."""
    if token == "":
        return 0.0
    if any(ord(c) > 127 for c in token):
        return -0.36  # non-Latin script
    core = token.strip()
    if CODE.search(core):
        return -0.1  # code-like
    if token.startswith(" ") and core.isalpha() and core.islower():
        return 0.29 if core in FUNCTION_WORDS else -0.06
    if core.isalpha() and core[:1].isupper():
        return -0.18  # capitalised word
    if core.isalpha():
        return -0.17  # bare lower-case word
    if core.isdigit():
        return -0.08
    if core == "":
        return 0.0  # pure whitespace
    return 0.1  # other punctuation


def step(carry, prefix, upstream):
    docs = prefix.document_ids
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(docs) > 1 else None
    first = len(docs) == 1 or docs[-1] != docs[-2]
    if first:
        carry = {"n": 1, "start": token, "all_cr": token == "\r"}
        if token == "//\n":
            return carry, 7.5
        if token == "\r":
            return carry, 6.06
        return carry, first_token_value(token)
    n = carry["n"] + 1
    carry = {"n": n, "start": carry["start"], "all_cr": carry["all_cr"] and token == "\r"}
    if carry["all_cr"]:
        return carry, 6.06  # the document opens with carriage returns
    if n == 2 and carry["start"] == "Title" and token == ":":
        return carry, -5.88
    if token == "··" and previous == "··":
        return carry, -0.665
    return carry, 0.0

