"""A document-initial, unchanging-prefix signal.

Predict a large negative value for initial letter tokens, weaker values for
symbols and digits, and a positive value for a single space or digits 0 and 1.
An initial run of identical tokens keeps the signal; the first different token
switches it off. Coarse script, case and word-form groups approximate strength,
without memorizing individual words or later small fluctuations.
"""
import keyword
import regex

READS = ()


def initial_strength(text):
    word = text.strip()
    letters = ''.join(c for c in word if c.isalpha())
    if text == '<|im_start|>':
        return -7.96
    if letters:
        if not regex.fullmatch(r'\p{Script=Latin}+', letters):
            return -6.2
        if keyword.iskeyword(word):
            return -5.0
        if not word[0].isalpha():
            return -5.8
        if letters.isupper():
            return -6.6
        if letters[0].isupper():
            return -8.7
        return -6.5 if len(letters) <= 2 else -7.6
    if '\ufffd' in text:
        return -3.8
    if text == ' ':
        return 1.27
    if text.isspace():
        return -1.5
    if word.isdigit():
        return 1.4 if word in ('0', '1') else -1.45
    return -1.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is not None and carry[0] == doc:
        if token == carry[1]:
            return carry, carry[2]
        return (doc, None, 0.0), 0.0
    value = initial_strength(prefix.token_strings[-1])
    return (doc, token, value), value

"""Local responses to written-out and misdecoded character encodings.

Quote entities are positive; many byte escapes and mojibake fragments are
negative. Split C1 controls depend on the preceding misdecoded character.
A few TeX/Isabelle escapes and the initial label 'Title:' are separate cases.
Only a bounded byte suffix is retained, resetting at document boundaries.
Unmatched positions return zero, omitting ordinary token-specific variation.
"""
import re

READS = ()

# Responses at the last piece of familiar typesetting/character escapes.
COMMANDS = {
    b'\\textup': -3.6,
    b'\\textnormal': -3.2,
    b'\\textsup': -4.0,
    b'\\textsc': -0.9,
    b'\\texttt': -1.0,
    b'\\textback': -1.3,
    b'\\footnotes': -1.4,
    b'\\footnotesize': 1.4,
    b'\\tabularnewline': 5.0,
    b'\\ensuremath': 1.5,
    b'\\frak': 1.4,
    b'\\xspace': 0.7,
    b'\\eqno': 0.7,
    b'\\<open': 5.8,
    b'\\<close': 4.1,
}

# Stages of a hexadecimal byte escape, not arbitrary token identities.
HEX_STAGES = {
    b'c2': -2.8,
    b'e2': -1.4,
    b'8': -1.1,
    b'9': -1.1,
    b'80': -1.9,
    b'9d': 1.7,
    b'93': 0.8,
    b'99': 0.6,
    b'0c': -1.7,
    b'a0': 2.7,
    b'ac': -1.9,
    b'ef': -2.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old = b''
    else:
        old = carry[1]
    token = prefix.token_bytes[-1]
    tail = (old + token)[-64:]
    value = 0.0
    prior = old.decode('utf8', 'ignore')

    if token == b'\xc2' and old:
        # C2 is the UTF-8 lead byte for Latin-1/C1 characters. These
        # preceding letters are common results of a wrong text encoding.
        if prior.endswith('โ'):
            value = -9.7
        elif prior.endswith('β'):
            value = -8.0
        elif prior.endswith(('π', '๐')):
            value = -4.5
        elif prior.endswith(('\x90', '\x9d')):
            value = -3.5
        else:
            value = -1.1
    elif len(token) == 1 and old.endswith(b'\xc2'):
        lead = old[:-1].decode('utf8', 'ignore')
        code = token[0]
        if lead.endswith(('โ', 'β')) and 0x80 <= code < 0xa0:
            value = -8.0 if code in (0x82, 0x88) else -6.0
        elif lead.endswith(('π', '๐')) and code == 0x9d:
            value = -6.8
        elif lead.endswith('\x9d') and code in (0x90, 0x91):
            value = -12.0
        elif lead.endswith('\x9d') and code == 0x93:
            value = -3.5
        elif code == 0x83:
            value = -2.4
        elif code == 0x8e:
            value = -1.7 if lead.endswith('\x88') else -4.7
        elif code == 0x8f:
            value = -1.8
    elif token == b':' and old == b'Title':
        value = -7.8
    elif token == b'4' and old.endswith(b'&#3'):
        value = 3.0
    elif token == b'9' and old.endswith(b'&#3'):
        value = 2.6
    elif token == b'3' and old.endswith(b'&#'):
        value = 0.3
    elif token == b' protected' and old.endswith(b'[email'):
        value = 1.8
    elif token.decode('utf8', 'ignore') == '‰' and prior.endswith('â'):
        value = -8.3
    elif token == '¬'.encode() and prior.endswith('п'):
        value = -12.5
    elif token == b'\xc2\x80\xc2' and prior.endswith(('â', 'โ')):
        value = -8.0 if prior.endswith('โ') else -4.7
    else:
        match = re.search(rb'\\x([0-9a-f]{0,2})$', tail)
        if not match:
            # Some scraped text has lost its escape backslashes entirely.
            chain = re.search(rb'x[ce]2(?:x[0-9a-f]{0,2})*$', tail)
            if chain:
                match = re.search(rb'x([0-9a-f]{0,2})$', chain[0])
        if match:
            digits = match[1]
            if digits and token == digits[-1:]:
                value = HEX_STAGES.get(digits, 0.0)
            elif digits in (b'ac', b'ef'):
                value = HEX_STAGES[digits]
            elif not digits and re.search(rb'x[0-9a-f]{2}$', old):
                value = -3.2 if old.endswith(b'xc2') else -0.9
            if digits == b'a0' and old.endswith(b'x96\\xa'):
                value = 0.5
        if token == b'q' and re.search(
            rb'\\(?:n|le|ge|prece|succe|sime)q$', tail
        ):
            value = 1.4
        for command, response in COMMANDS.items():
            if tail.endswith(command) and len(token) < len(command):
                value = response
                break
    return (doc, tail), value

"""A partial surface approximation with several separate response families.

For line-leading runs of 2–12 spaces with even length, a repetition count
weakens the prediction as that width recurs. Block openers raise it.
Other rules recognize selected numeral completions, shortness stems, Chinese
numbered demonstratives, and ro-like syllables. Unrecognized tokens get zero.
Substantial lexical and context-dependent variation remains unexplained.
"""
import calendar
import re
import unicodedata

READS = ()
ALPHA = 0.5
BASE, FOUR, PLAIN, SENTENCE, OPENER = 0.41, 0.16, 0.17, 0.32, 0.11
MONTHS = '|'.join(calendar.month_name[1:] + calendar.month_abbr[1:])
DATE = re.compile(r'\b(?:' + MONTHS + r')\s+3[01]$', re.I)


def lexical_value(t, p, text):
    if len(t) == 1 and t.isdecimal():
        if p == '3' and t in '01':
            date = DATE.search(text) or re.search(r'[:月/-]3[01]$', text)
            return (0.75 if date else 0.45) if t == '0' else (
                0.65 if date else 0.22
            )
        if p == '2' and t == '0':
            return -0.09
        if t == '9':
            return 0.105 if p == '1' else 0.02
    if t == '九' and p.endswith('一'):
        return 2.4
    if text.lower().endswith('shortly'):
        return 0.8
    if t.strip().lower() in ('short', 'shorter', 'shortest'):
        return 0.15
    if t.lower() in ('ort', 'orte') and text.lower().endswith(('short', 'shorte')):
        return 0.95
    if re.search(r'kurz\w*$', text, re.I):
        return 1.05
    if re.search(r'kort\w*$', text, re.I):
        return 0.55
    if t.strip().lower() == 'thirty':
        return 0.47
    if t in ('z', 'zen', 'zes') and p.lower().endswith(('r', 'l')):
        if len(p.strip()) <= 4 and p not in (' er', ' der'):
            return 0.22
    if re.fullmatch(r'[一两二]?[个种场次款具份]', t):
        prior = text[:-len(t)]
        if re.search(r'[这那哪](?:一|两|二)?$', prior):
            counted = t.startswith(('一', '两', '二'))
            counted = counted or prior.endswith(('一', '两', '二'))
            if counted:
                return 1.4
    # Syllables roughly romanized ro/ru/luo in four writing systems.
    if t in ('ロ', '로', 'رو', '罗', '洛'):
        return 0.27
    if t == '://' and p.lower().endswith(('http', 'https')):
        return 0.23
    if t.strip().lower() == 'questions' and p.strip().lower() in (
        'similar', 'related'
    ):
        return -0.55
    if t in ('<|im_end|>', '</tool_call>', '</tool_response>'):
        return -0.07
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, counts = '', '', {}
    else:
        _, previous, recent, counts = carry
    t = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    text = (recent + t)[-40:]
    value = 0.0
    if t and not t.strip(' '):
        n = len(t)
        seen = counts.get(n, 0)
        if previous.endswith('\n'):
            if 2 <= n <= 12 and n % 2 == 0:
                novelty = (1 + seen) ** -ALPHA
                end = previous.rstrip()
                value = (BASE + FOUR * (n == 4) - PLAIN * (not end)
                         - SENTENCE * end.endswith(('.', '。'))) * novelty
                value += OPENER * end.endswith(('{', '[', '(', ':'))
            elif n in (3, 5):
                value = -0.05
        counts[n] = seen + 1
    elif t.startswith('\t') and not t.strip('\t '):
        n = len(t) - len(t.rstrip(' '))
        value = 0.24 if n >= 2 and n % 2 == 0 else 0.0
    else:
        value = lexical_value(t, previous, text)
    return (doc, t, text, counts), float(value)

