"""Layer 1, MLP down-projection, component 4794: a JavaScript / TypeScript code detector.

It stays near zero on ordinary prose and most code, and spikes on a few tokens that mark
modern front-end source code:

- the arrow of an arrow function, "=>", right after the closing parenthesis of its
  parameter list ("() =>", "(node) =>"): the strongest and most consistent trigger;
- TypeScript / JavaScript file names ("index.ts", "Button.tsx", "app.js") and the "x" of ".tsx";
- "import ... from" lines, JSX elements returned by a component ("return (" then "<"),
  "export", "const x =" declarations, and "return";
- front-end library names (React, Next, Vue, Svelte-style "velte", Ember, props, webpack).

Everything else predicts 0; the start of each document predicts a small negative value.
"""

READS = ()

import re

# TypeScript / JavaScript file endings, e.g. "Button.tsx", "index.js".
TS_JS_FILE = {".ts": 2.6, ".tsx": 2.6, ".js": 1.2, ".jsx": 1.2, ".vue": 2.0}

# Front-end library and framework names, as they appear in code and import paths.
FRONTEND = {
    "React": 3.0, " React": 3.0, "react": 2.0, "/react": 2.0, "ReactDOM": 3.0,
    "JSX": 2.5, "jsx": 2.5, "Next": 1.5, " Next": 1.5, "-next": 3.0,
    "Ember": 2.0, "ember": 2.0, "velte": 2.0, "Angular": 2.0, "Detection": 2.5,
    "Relay": 2.5, "Turbo": 3.0, " Turbo": 3.0, "Props": 2.0, "props": 3.0, " props": 3.0,
    " prop": 1.5, "Mount": 2.0, "mount": 1.5, " mount": 1.5, "Ref": 1.0, "router": 1.5,
    "expect": 1.0, " expect": 1.0, "jest": 2.0, "lint": 1.0, "eslint": 2.0,
    " TS": 2.0, "TS": 2.0, "typescript": 2.0, " ts": 1.2, "_modules": 1.0, "/components": 2.0,
    "Component": 1.5, "webpack": 1.5, "npm": 1.0, "Middleware": 3.0, "Mounted": 3.0,
    "Thunk": 3.0, "Reducer": 2.0,
}

DOC_START = -0.2  # first token of a document (after <|endoftext|>, or the row's first token)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, DOC_START
    prev = prefix.token_strings[-2]
    recent = "".join(prefix.token_strings[-8:])

    # Arrow functions: "=>" after a parameter list ")" is strong; after a bare name, weaker;
    # after a quoted key (PHP-style "'key' => value") it is off.
    if tok.startswith(" =>"):
        if prev.endswith(")"):
            return carry, 4.0
        if re.search(r"\w$", prev):
            return carry, 0.7
        return carry, 0.0
    if tok == " ()":
        return carry, 2.0
    if tok == "x" and prev.endswith(".ts"):  # ".tsx" is split into ".ts" + "x"
        return carry, 4.0
    if tok in (" <", "<") and re.search(r"(return|=>)\s*\(\s*$", "".join(prefix.token_strings[-4:-1])):
        return carry, 4.0  # a JSX element being returned
    if tok == " from" and "import" in recent:
        return carry, 2.0
    if tok in TS_JS_FILE:
        return carry, TS_JS_FILE[tok]
    if tok in FRONTEND:
        return carry, FRONTEND[tok]
    if tok == " =" and re.search(r"\b(const|let|var)\b", recent):
        return carry, 0.8
    if tok in (" return", "\treturn"):
        return carry, 0.7
    if tok == "export":
        return carry, 1.1
    return carry, 0.0

