"""A spelling-sensitive God/Gott detector, with a smaller con/com response.

Literal God and German Gott roots dominate. Split pieces completing these
roots also fire; short g-to-o joins fire more weakly. Con/com is stronger
in Spanish/Italian/Portuguese prose than in English or source code. This
is a local word-piece detector, not a general detector of religious topics.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=20000)
def frequency(word, language):
    return zipf_frequency(word, language)


def romance_context(text, languages):
    words = re.findall(r'[^\W\d_]+', text.lower())[-15:]
    if not words:
        return False
    def score(language):
        return sum(frequency(w, language) for w in words) / len(words)
    others = ('en', 'vi', 'fr', 'de')
    return max(map(score, languages)) > max(map(score, others)) + 0.3


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, history = '', ''
    if carry is not None and carry[0] == doc:
        previous, history = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    attached = bool(token) and token[0].isalpha()
    after_g = attached and previous.lower().endswith('g')
    core = 'g' + lower if after_g else lower
    value = 0.0

    if lower == 'god':
        if word.isupper():
            value = 7.9
        elif word[0].isupper():
            value = 5.0 if token.startswith(' ') else 6.0
        else:
            value = 4.0 if token.startswith(' ') else 3.5
    elif lower == 'gods':
        value = 0.8
    elif core == 'gott':
        value = 4.2 if after_g else 5.8
    elif core == 'gottes':
        value = 8.0 if after_g else 7.5
    elif (core in ('göt', 'gött')
          or (lower == 'tt' and previous.lower().endswith('gö'))):
        value = 6.0
    elif lower == 'gö':
        value = 2.0
    elif after_g and core.startswith('god') and len(core) <= 5:
        value = 3.0 if core == 'god' else 4.0
    elif word == 'Dios':
        value = 5.8
    elif word == 'Deus':
        value = 3.1
    elif word == 'Бог':
        value = 2.8
    elif word == '神':
        value = 0.8
    elif lower == 'gon':
        value = 4.8 if attached else (2.5 if word[0].isupper() else 1.6)
    elif (after_g and lower.startswith('o')
          and word.isalpha() and len(word) <= 7):
        value = 0.6
    elif lower in ('con', 'com'):
        languages = ('es', 'it') if lower == 'con' else ('pt',)
        if token.startswith(' ') and romance_context(history, languages):
            value = 1.3 if lower == 'con' else 1.0
        elif lower == 'con' and word.islower():
            after_vowel = bool(previous) and previous[-1:].lower() in 'aeiou'
            value = 2.4 if attached and after_vowel else 0.3

    return (doc, token, (history + token)[-180:]), value

