FACADES = {
    'DB', 'Route', 'Storage', 'Schema', 'Auth', 'Cache', 'Session', 'View',
    'Log', 'Config', 'Request', 'Response', 'Validator', 'Redirect', 'Mail',
    'Queue', 'Event', 'Input',
