import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()
LOCK_ENDINGS = {
    '': -8.8, 's': -8.4, 'ed': -6.5, 'ing': -6.3,
    'er': -5.2, 'smith': -0.8,
}


@lru_cache(maxsize=160000)
def spelling(text):
    for c in text:
        if c.isalpha() and not unicodedata.name(c, '').startswith(
            ('LATIN', 'CYRILLIC', 'GREEK')
        ):
            return ' '
    return anyascii(text)


def response(token, previous, word):
    s = spelling(token)
    low = s.lower()
    bare = low.lstrip(' ._-\t\n')
    joined = bool(s and s[0].isalpha())
    word = word.lower()
    if token in ('锁', '鎖'):
        return -7.0
    if any(c in token for c in '锁鎖'):
        return -3.1 if '解' in token else -4.0
    if token == '住' and any(c in previous for c in '锁鎖'):
        return -5.0
    if token == 'ロック':
        return -2.4
    if bare.startswith('lock') and bare[4:] in LOCK_ENDINGS:
        if joined and word.endswith(('b', 'c', 'f')):
            return 0.3
        if joined and word.endswith('inter'):
            return -11.6
        if bare == 'lock':
            if s.startswith('_'):
                return -4.7
            if s.startswith('.L'):
                return -6.6
            return -11.2 if s.startswith('-') else -8.8
        return LOCK_ENDINGS[bare[4:]]
    if bare.startswith('unlock'):
        return -2.1 if s.startswith(('_', '.')) else -3.4
    if bare == 'deadlock':
        return -5.8
    if joined and low in ('ock', 'ocks', 'ocked', 'ocking'):
        if word.endswith('l'):
            return -9.9
        if word.endswith('n'):
            return -3.6
    if joined and s == 'ok' and word.endswith('l'):
        return -1.5
    if bare == 'kn':
        return -1.2 if s.strip().isupper() else -2.0
    if bare.startswith('knock') and bare[5:] in ('', 'ed', 'ing'):
        return -2.6 if bare == 'knock' else -1.5
    if joined and low in ('n', 'ne', 'ner', 'na', 'no') and word.endswith('k'):
        return -1.3 if s == 'N' else -4.2
    if joined and low in ('s', 'ing', 'ed', 'er', 'ers'):
        if word.endswith('unlock'):
            return -2.9
        if word.endswith('lock') and not word.endswith(('block', 'clock', 'flock')):
            return -3.0 if low in ('er', 'ers') else -8.2
    if bare == 'lain':
        return 2.1 if joined else 6.5
    if low == 'ain' and word.endswith('l'):
        return 4.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, word = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, word)
    match = re.search(r'[A-Za-z]+$', word + spelling(token))
    word = match.group()[-64:] if match else ''
    return (doc, token, word), value

"""Approximate comma roles using phrase length and elementary grammar.

Short introductory phrases and discourse markers get negative values; complete
clause-like phrases get higher values. Lengths count tokens since punctuation;
phrase text is limited to 240 characters. Comma shape changes the scale. Certain
following determiners, quantifiers, possessives and adverbs get a continuation
response, stronger after a positive comma. Other tokens are near zero. This is
a heuristic, not a full syntactic parser.
"""
import math
import re

READS = ()
PREPOSITIONS = set(
    ('in on at for with without from by to after before despite during '
     'under over between among through upon within beyond into').split()
)
SUBORDINATORS = set(('if when while although though because since unless until '
                     'once whenever wherever whereas as whether').split())
SUBJECTS = set(('the a an this that these those i you he she it we they '
                'my your his her its our their').split())
AUXILIARIES = set(('is are was were am be been being has have had do does did '
                   'will would can could should shall may might must').split())
CONNECTIVES = set(('however therefore hence thus indeed moreover furthermore '
                   'nevertheless nonetheless consequently accordingly similarly '
                   'conversely otherwise instead meanwhile finally firstly secondly '
                   'thirdly namely specifically particularly notably importantly '
                   'briefly alternatively still plus').split())
INTERJECTIONS = set('yes no well wait okay ok sure hmm oh ah look'.split())
ADVERBS = set('even only often also still just then perhaps'.split())
MARKERS = {'for example', 'for instance', 'in fact', 'in other words',
           'of course', 'after all', 'that is', 'i mean', 'you know',
           'in particular', 'in short', 'first of all', 'on the other hand'}


def phrase_value(phrase, sentence_length, phrase_length):
    words = re.findall(r"[a-z]+(?:'[a-z]+)?", phrase.lower())
    if len(words) > 1 and words[0] in {'and', 'but', 'so'}:
        words = words[1:]
    first = words[0] if words else ''
    last = words[-1] if words else ''
    text = ' '.join(words)
    value = 0.294
    if sentence_length:
        value -= 0.407 * math.exp(-sentence_length / 4)
    if phrase_length:
        value -= 0.681 * math.exp(-phrase_length / 4)
    if first in PREPOSITIONS:
        value -= 0.424
    if first in SUBORDINATORS:
        value -= 0.535
    if first in SUBJECTS:
        value += 0.393
    if AUXILIARIES.intersection(words):
        value += 0.297
    if last in CONNECTIVES or text in MARKERS:
        value -= 1.218
    if text in INTERJECTIONS:
        value -= 0.799
    if len(words) == 1 and last.endswith('ly'):
        value -= 0.258
    if phrase.rstrip() and phrase.rstrip()[-1].isdigit():
        value += 0.141
    if any(c in phrase for c in '={['):
        value -= 0.148
    return value


def continuation(word, signal):
    if word in {'each', 'every', 'either', 'neither'}:
        return 0.62 + 2.096 * signal
    if word in {'both', 'all'}:
        return 0.516 + 1.637 * signal
    if word in {'some', 'any'}:
        return 0.169 + 2.207 * signal
    if word == 'one':
        return 0.108 + 1.234 * signal
    if word in {'the', 'a', 'an', 'this', 'that', 'these', 'those'}:
        return 0.11 + 0.907 * signal
    if word in {'his', 'her', 'their', 'our', 'my', 'its', 'your'}:
        return 0.504 + 1.112 * signal
    if word in ADVERBS or (word.isalpha() and word.endswith('ly')):
        return 0.024 + 0.433 * signal
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, '', False, 0.)
    _, ns, nc, phrase, was_comma, previous_value = carry
    token = prefix.token_strings[-1]
    is_comma = any(c in token for c in ',，、،')
    value = -0.003
    if is_comma:
        value = phrase_value(phrase, ns, nc)
        if '、' in token:
            value = -0.619
        elif '，' in token:
            value = -0.145
        elif '،' in token:
            value = -0.145
        elif '\n' in token:
            value = -0.067
        elif token.strip() == ',':
            pass
        elif '.' in token:
            value = -0.27
        elif any(c in token for c in ')]}'):
            value = 0.196 + 0.545 * value
        else:
            value = 0.052 + 0.245 * value
    elif was_comma:
        value = continuation(token.strip().lower(), max(0., previous_value))
    ns = 0 if re.search(r'[.!?。！？\n]', token) else ns + 1
    nc = 0 if re.search(r'[,，、،;；:：.!?。！？\n]', token) else nc + 1
    phrase = re.split(r'[,，、،;；:：.!?。！？\n]', phrase + token)[-1][-240:]
    return (doc, ns, nc, phrase, is_comma, value), float(value)
